-- supabase/migrations 0001 through 0122 in order (0122_smart_triage).
-- GENERATED by supabase/baseline/build.sh, which also proves it: loaded
-- into a clean database, every check in supabase/tests passes. Do not
-- edit by hand; add a migration and rebuild.
--
-- For a NEW Supabase project only (enable postgis and pg_cron first):
--   psql "$DATABASE_URL" -f supabase/baseline/baseline.sql
--   psql "$DATABASE_URL" -f supabase/seed.sql
-- then mark the migrations it covers as applied, so db push skips them:
--   supabase migration repair --status applied 0001 0002 0003 0004 0005 0006 0007 0008 0009 0010 0011 0012 0013 0014 0015 0016 0017 0018 0019 0020 0021 0022 0023 0024 0025 0026 0027 0028 0029 0030 0031 0032 0033 0034 0035 0036 0037 0038 0039 0040 0041 0042 0043 0044 0045 0046 0047 0049 0050 0051 0052 0053 0054 0055 0056 0057 0058 0059 0060 0061 0062 0063 0064 0065 0066 0067 0068 0069 0070 0071 0072 0073 0074 0075 0076 0077 0078 0079 0080 0081 0082 0083 0084 0085 0086 0087 0088 0089 0090 0091 0092 0093 0094 0095 0096 0097 0098 0099 0100 0101 0102 0103 0104 0105 0106 0107 0114 0115 0116 0117 0118 0119 0120 0121 0122 
-- The live project keeps its migration history; never run this there.

create extension if not exists pgcrypto with schema extensions;
create extension if not exists pg_trgm with schema extensions;
create extension if not exists postgis;
create extension if not exists pg_cron;

-- Supabase grants every new table, sequence and function in public to the
-- API roles by default. The grants below are the exact ones the
-- migrations ended with (including every revoke), so that default is off
-- while this file loads and back on at the end.
alter default privileges in schema public revoke all on tables from anon, authenticated, service_role;
alter default privileges in schema public revoke all on sequences from anon, authenticated, service_role;
alter default privileges in schema public revoke all on functions from anon, authenticated, service_role;
