--
-- Name: _add_report_evidence(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._add_report_evidence(p_report uuid, p_log uuid, p_kind text, p_media jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  m jsonb;
begin
  if jsonb_array_length(coalesce(p_media, '[]'::jsonb)) > 6 then
    raise exception 'At most 6 photos';
  end if;
  for m in select * from jsonb_array_elements(coalesce(p_media, '[]'::jsonb)) loop
    insert into public.report_evidence (report_id, posted_by, kind, media_url, mime_type, bytes, log_id)
    values (p_report, auth.uid(), p_kind, m->>'media_url', m->>'mime_type', (m->>'bytes')::integer, p_log);
  end loop;
end $$;


--
-- Name: _case_guard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._case_guard(p_report uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_h   uuid;
  v_name text;
begin
  if p_report is null or v_uid is null or not public.is_admin() then
    return;
  end if;
  if current_setting('smartsumbong.handler_change', true) = 'on' then
    return;
  end if;
  select handler_id into v_h from public.reports where id = p_report;
  if v_h is null then
    perform set_config('smartsumbong.handler_change', 'on', true);
    update public.reports set handler_id = v_uid, handled_since = now()
     where id = p_report and handler_id is null;
    insert into public.case_handler_log (report_id, admin_id, action) values (p_report, v_uid, 'take');
    perform set_config('smartsumbong.handler_change', 'off', true);
  elsif v_h <> v_uid then
    select public.display_name(full_name) into v_name from public.users where id = v_h;
    raise exception '% is handling this case. Take it over to act on it.', coalesce(v_name, 'Another administrator');
  end if;
end $$;


--
-- Name: _case_guard_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._case_guard_report() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_name text;
begin
  new.version := coalesce(old.version, 0) + 1;
  if v_uid is null or current_setting('smartsumbong.handler_change', true) = 'on' or not public.is_admin() then
    return new;
  end if;
  if old.handler_id is null then
    new.handler_id := v_uid;
    new.handled_since := now();
    insert into public.case_handler_log (report_id, admin_id, action) values (new.id, v_uid, 'take');
  elsif old.handler_id <> v_uid then
    select public.display_name(full_name) into v_name from public.users where id = old.handler_id;
    raise exception '% is handling this case. Take it over to act on it.', coalesce(v_name, 'Another administrator');
  end if;
  return new;
end $$;


--
-- Name: _case_guard_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._case_guard_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_table_name = 'report_messages' then
    if new.from_barangay then perform public._case_guard(new.report_id); end if;
  elsif tg_table_name = 'dispatch_updates' then
    perform public._case_guard((select report_id from public.dispatches where id = new.dispatch_id));
  else
    perform public._case_guard(new.report_id);
  end if;
  return new;
end $$;


--
-- Name: _clear_alerts_except(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._clear_alerts_except(p_prefix text, p_keep text[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.system_alerts set cleared_at = now(), checked_at = now()
   where key like p_prefix || '%' and cleared_at is null and not (key = any (p_keep));
$$;


--
-- Name: _dispatch_cap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._dispatch_cap_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_n int;
begin
  if new.state not in ('assigned', 'accepted') then return new; end if;
  if tg_op = 'UPDATE' and old.state in ('assigned', 'accepted') and old.tanod_id = new.tanod_id then
    return new;   -- the same live dispatch moving between live states
  end if;
  perform pg_advisory_xact_lock(hashtext('dispatch-cap:' || new.tanod_id::text));
  select count(*) into v_n from public.dispatches
   where tanod_id = new.tanod_id and state in ('assigned', 'accepted') and id <> new.id;
  if v_n >= public.tanod_dispatch_cap() then
    raise exception 'This tanod already has % dispatches, the most at once.', v_n;
  end if;
  return new;
end $$;


--
-- Name: _notify_admins(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._notify_admins(p_message text, p_subject uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.notifications (user_id, kind, message, subject_user_id)
  select a.id, 'status_change', p_message, p_subject from public.users a
   where a.role = 'admin' and not coalesce(a.is_suspended, false);
$$;


--
-- Name: _raise_alert(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._raise_alert(p_key text, p_message text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_was_open boolean;
begin
  select cleared_at is null into v_was_open from public.system_alerts where key = p_key;
  insert into public.system_alerts as a (key, message)
  values (p_key, p_message)
  on conflict (key) do update
     set message = excluded.message,
         checked_at = now(),
         raised_at = case when a.cleared_at is null then a.raised_at else now() end,
         cleared_at = null;
  if not coalesce(v_was_open, false) then
    perform public._notify_admins('System check: ' || p_message);
  end if;
end $$;


--
-- Name: is_media_url(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_media_url(p_url text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  select p_url ~
    '^https://res\.cloudinary\.com/nwb2kryl/image/upload/v[0-9]+/(reports|ids|selfies|dispatch|avatars)/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|jpeg|png|webp)$'
      or p_url ~
    '^https://res\.cloudinary\.com/nwb2kryl/image/authenticated/v[0-9]+/(ids|selfies)/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|jpeg|png|webp)$'
$_$;


--
-- Name: FUNCTION is_media_url(p_url text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_media_url(p_url text) IS 'True only for delivery URLs in the barangay''s own Cloudinary cloud: public images under reports, ids, selfies, dispatch or avatars, or private (authenticated) images under ids or selfies (0117), with a UUIDv4 object name, an image extension, no signature and no query string. Mirrored by _pinnedUrl in mobile/core/lib/src/media_upload.dart.';


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid NOT NULL,
    full_name text NOT NULL,
    email text,
    mobile_number text NOT NULL,
    role public.user_role DEFAULT 'resident'::public.user_role NOT NULL,
    id_image_url text,
    verification_status public.verification_state DEFAULT 'pending'::public.verification_state NOT NULL,
    verification_submitted_at timestamp with time zone,
    verification_due_at timestamp with time zone,
    verified_at timestamp with time zone,
    verified_by uuid,
    rejection_reason text,
    duty_status public.duty_state,
    is_dispatchable boolean DEFAULT false NOT NULL,
    is_suspended boolean DEFAULT false NOT NULL,
    suspended_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_geom public.geography(Point,4326),
    last_location_at timestamp with time zone,
    selfie_url text,
    id_type public.id_document_type,
    verification_overdue_notified_at timestamp with time zone,
    must_change_password boolean DEFAULT false NOT NULL,
    address text,
    avatar_url text,
    ocr_detected_type public.id_document_type,
    ocr_flags text[] DEFAULT '{}'::text[] NOT NULL,
    ocr_extracted_name text,
    ocr_extracted_number text,
    ocr_processed_at timestamp with time zone,
    muted_notification_kinds public.notification_kind[] DEFAULT '{}'::public.notification_kind[] NOT NULL,
    ocr_rescan_requested_at timestamp with time zone,
    is_retired boolean DEFAULT false NOT NULL,
    retired_at timestamp with time zone,
    admin_handover_until timestamp with time zone,
    admin_handover_role public.user_role,
    admin_handover_successor_id uuid,
    removed_at timestamp with time zone,
    CONSTRAINT duty_only_for_tanod CHECK (((duty_status IS NULL) OR (role = 'tanod'::public.user_role))),
    CONSTRAINT users_address_check CHECK (((address IS NULL) OR (char_length(address) <= 200))),
    CONSTRAINT users_avatar_url_pinned CHECK (((avatar_url IS NULL) OR public.is_media_url(avatar_url))),
    CONSTRAINT users_id_image_url_pinned CHECK (((id_image_url IS NULL) OR public.is_media_url(id_image_url))),
    CONSTRAINT users_selfie_url_pinned CHECK (((selfie_url IS NULL) OR public.is_media_url(selfie_url)))
);


--
-- Name: COLUMN users.email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.email IS 'Contact address, not a credential. Optional: many residents do not have one. Sign-in identity is derived from mobile_number — see public.auth_email_for(). Postgres allows multiple NULLs under a unique constraint, so the uniqueness of real addresses still holds.';


--
-- Name: COLUMN users.mobile_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.mobile_number IS 'The identity. Normalised to +639XXXXXXXXX at signup, unique, and the basis of the synthetic auth address. Changing it changes how the resident signs in.';


--
-- Name: COLUMN users.selfie_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.selfie_url IS 'Optional liveness photo. Nullable: the Register Account use case does not require it. See 0013 header.';


--
-- Name: COLUMN users.id_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.id_type IS 'Which document id_image_url photographs. Chosen by the applicant at signup and shown to the admin during verification — the check differs by document, so the label is part of the evidence. Null on accounts created before 0019.';


--
-- Name: COLUMN users.verification_overdue_notified_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.verification_overdue_notified_at IS 'When admins were told this account passed its two-hour verification window. Non-null suppresses further notices; cleared on re-entry to pending. Bookkeeping for sweep_overdue_verifications(), not a service-level record — verification_due_at is that.';


--
-- Name: COLUMN users.must_change_password; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.must_change_password IS 'Set when an administrator issues a temporary password. The client is required to force a change before allowing any other action.';


--
-- Name: COLUMN users.address; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.address IS 'Free text, resident-editable directly (0038) — a "how to find your house" line for the barangay, not a geocoded value anything spatial reads. Unlike full_name/mobile_number this is not identity evidence, so guard_privileged_user_fields() (0026) does not restrict it.';


--
-- Name: COLUMN users.avatar_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.avatar_url IS 'Resident-editable directly (0038), same pattern as email. Pinned to this project''s own Cloudinary account by users_avatar_url_pinned, same as id_image_url/selfie_url.';


--
-- Name: COLUMN users.ocr_detected_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_detected_type IS 'ID type OCR read off the photograph itself (header/keyword match), independent of id_type which is what the applicant selected in the dropdown. The two disagreeing is a flag, not an error — see ocr_flags.';


--
-- Name: COLUMN users.ocr_flags; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_flags IS 'Machine-generated triage flags from the Flutter client''s on-device OCR pass, e.g. type_mismatch, unreadable, name_mismatch, no_id_number. Advisory only: never gates verify_user_account, only orders/labels the admin''s queue. Empty array means OCR ran and raised nothing, NOT that OCR never ran — check ocr_processed_at for that.';


--
-- Name: COLUMN users.ocr_extracted_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_extracted_name IS 'Name OCR read off the ID photo, for the admin to eyeball against full_name. Not normalised, not used in any automated comparison beyond the name_mismatch flag the client itself may set.';


--
-- Name: COLUMN users.ocr_extracted_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_extracted_number IS 'ID number OCR read off the photo (e.g. license or PhilSys number), shown to the admin for their own manual cross-check. Never validated against any external registry — see this file''s header.';


--
-- Name: COLUMN users.ocr_processed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_processed_at IS 'When the client''s OCR pass ran. Null means it never ran (older app build, permission denied, or skipped) — distinct from it having run and found nothing to flag.';


--
-- Name: COLUMN users.muted_notification_kinds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.muted_notification_kinds IS 'Notification kinds this user does not want a phone push for. Never suppresses the public.notifications row itself -- only checked by send-dispatch-push before it calls FCM. See 0044.';


--
-- Name: COLUMN users.ocr_rescan_requested_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_rescan_requested_at IS 'Set by request_ocr_rescan() when an admin asks for a fresh OCR read on this account''s already-uploaded ID photo. Cleared by the resident''s own app (AuthService.submitIdOcrResult) once it has re-run on-device OCR and written a new result. Null means no re-check is pending.';


--
-- Name: COLUMN users.is_retired; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.is_retired IS 'Set only by finalize_retirement() on approval. Never a self-service flag — see 0052 header.';


--
-- Name: COLUMN users.retired_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.retired_at IS 'When an admin approved the retirement request. Null until then.';


--
-- Name: COLUMN users.admin_handover_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.admin_handover_until IS 'Set by promote_to_admin()''s optional handover window (0055). When reached, run_admin_handover_expirations() reverts this admin back to admin_handover_role automatically. Null outside an active handover.';


--
-- Name: COLUMN users.admin_handover_role; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.admin_handover_role IS 'Role this admin returns to when admin_handover_until passes -- captured at scheduling time, since an unattended sweep has no one to ask once the window actually ends.';


--
-- Name: COLUMN users.admin_handover_successor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.admin_handover_successor_id IS 'Who this admin is training during the handover window. Display only -- the successor already has full, independent admin access from the moment they are promoted; this is not a permission gate.';


--
-- Name: _resolution_tanod(uuid, text, public.report_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._resolution_tanod(p_report uuid, p_remark text, p_new_status public.report_status) RETURNS public.users
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select u.*
    from public.dispatches d
    join public.users u on u.id = d.tanod_id
   where p_new_status = 'resolved'
     and d.report_id = p_report
     and d.state = 'resolved'
     and nullif(trim(d.field_report_text), '') is not null
     and trim(d.field_report_text) = trim(coalesce(p_remark, ''))
   order by d.resolved_at desc nulls last
   limit 1
$$;


--
-- Name: _smart_triage_after_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._smart_triage_after_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  k public.smart_rules%rowtype;
  v_id uuid;
begin
  perform public.smart_triage(new.id);
  select * into k from public.smart_rules where id = 1;
  for v_id in
    select o.id from public.reports o
     where o.id <> new.id
       and o.category = new.category
       and o.deleted_at is null
       and o.status not in ('resolved', 'closed', 'archived', 'rejected', 'cancelled')
       and o.created_at > new.created_at - make_interval(hours => k.corroboration_hours)
       and st_dwithin(o.geom, new.geom, greatest(k.corroboration_metres, k.duplicate_metres))
     limit 20
  loop
    perform public.smart_triage(v_id);
  end loop;
  return null;
exception when others then
  raise warning 'SMART triage after write failed: %', sqlerrm;
  return null;
end $$;


--
-- Name: _temp_password(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._temp_password() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_alpha text := 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  v_digit text := '23456789';
  v       text := '';
  i       integer;
begin
  for i in 1..4 loop v := v || substr(v_alpha, 1 + floor(random() * length(v_alpha))::int, 1); end loop;
  v := v || '-';
  for i in 1..4 loop v := v || substr(v_digit, 1 + floor(random() * length(v_digit))::int, 1); end loop;
  v := v || '-';
  for i in 1..3 loop v := v || substr(v_alpha, 1 + floor(random() * length(v_alpha))::int, 1); end loop;
  return v;
end $$;


--
-- Name: accept_dispatch(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_dispatch(p_dispatch uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_report uuid; v_old report_status;
begin
  update public.dispatches
     set state = 'accepted', accepted_at = now(), is_primary = true
   where id = p_dispatch
     and tanod_id = auth.uid()
     and state = 'assigned'
  returning report_id into v_report;

  if v_report is null then
    raise exception 'Dispatch not found, not yours, or already actioned';
  end if;

  select status into v_old from public.reports where id = v_report;

  update public.reports set status = 'in_progress' where id = v_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status)
  values (v_report, auth.uid(), v_old, 'in_progress');
end $$;


--
-- Name: account_audit; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_audit (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subject_id uuid NOT NULL,
    actor_id uuid,
    action text NOT NULL,
    detail text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    prev_hash text,
    entry_hash text
);


--
-- Name: TABLE account_audit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.account_audit IS 'Append-only record of promotions, step-downs and other account state changes. Deliberately outside status_logs, which is per-report.';


--
-- Name: account_audit_fingerprint(public.account_audit); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_audit_fingerprint(a public.account_audit) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select concat_ws('|',
    a.id::text, a.subject_id::text, coalesce(a.actor_id::text, ''),
    a.action, coalesce(a.detail, ''),
    to_char(a.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'))
$$;


--
-- Name: account_directory(public.user_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_directory(p_role public.user_role) RETURNS TABLE(id uuid, full_name text, email text, mobile_number text, role public.user_role, verification_status public.verification_state, is_suspended boolean, duty_status public.duty_state, id_image_url text, selfie_url text, rejection_reason text, submitted_at timestamp with time zone, due_at timestamp with time zone, minutes_left integer, is_overdue boolean, holding_incident boolean, created_at timestamp with time zone, ocr_detected_type public.id_document_type, ocr_flags text[], ocr_extracted_name text, ocr_extracted_number text, abuse_strike_count integer, ocr_processed_at timestamp with time zone, ocr_rescan_requested_at timestamp with time zone, id_type public.id_document_type, suspended_reason text, is_retired boolean, retired_at timestamp with time zone, avatar_url text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select u.id, u.full_name, u.email, u.mobile_number, u.role,
         u.verification_status, u.is_suspended, u.duty_status,
         u.id_image_url, u.selfie_url, u.rejection_reason,
         u.verification_submitted_at,
         u.verification_due_at,
         case when u.verification_status = 'pending' and u.verification_due_at is not null
              then (extract(epoch from (u.verification_due_at - now())) / 60)::integer
         end,
         u.verification_status = 'pending'
           and u.verification_due_at is not null
           and u.verification_due_at < now(),
         exists (select 1 from public.dispatches d
                  where d.tanod_id = u.id and d.state in ('assigned', 'accepted')),
         u.created_at,
         u.ocr_detected_type,
         u.ocr_flags,
         u.ocr_extracted_name,
         u.ocr_extracted_number,
         (select count(*)::integer from public.status_logs sl
           join public.reports r2 on r2.id = sl.report_id
          where r2.resident_id = u.id
            and sl.is_abusive = true
            and sl.new_status = 'rejected'),
         u.ocr_processed_at,
         u.ocr_rescan_requested_at,
         u.id_type,
         u.suspended_reason,
         u.is_retired,
         u.retired_at,
         u.avatar_url
    from public.users u
   where u.role = p_role
     and u.removed_at is null
   order by (u.verification_status = 'pending') desc,
            cardinality(u.ocr_flags) > 0 desc,
            u.verification_due_at nulls last,
            u.full_name
$$;


--
-- Name: FUNCTION account_directory(p_role public.user_role); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.account_directory(p_role public.user_role) IS 'Residents / Personnel list. Pending first, then flagged-by-OCR first within that, soonest deadline after. Carries id_type, suspended_reason (0051), is_retired/retired_at (0052) and now avatar_url (0054) so Personnel/Residents can show the same profile picture the mobile app Edit Profile screen lets someone set for themselves.';


--
-- Name: admin_barangay_update(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_barangay_update(p_report uuid, p_body text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_body   text := nullif(trim(coalesce(p_body, '')), '');
  v_count  integer := jsonb_array_length(coalesce(p_media, '[]'::jsonb));
  v_log    uuid;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may post a barangay update';
  end if;
  if v_body is null and v_count = 0 then
    raise exception 'Write an update or attach a photo';
  end if;
  if v_body is not null and char_length(v_body) > 500 then
    raise exception 'The update can be at most 500 characters';
  end if;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if v_report.status in ('pending_review', 'closed', 'archived', 'rejected', 'cancelled') then
    raise exception 'Updates can be posted on an accepted, open complaint';
  end if;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, v_report.status,
          coalesce('Update from the barangay: ' || v_body,
                   format('The barangay added %s photo(s).', v_count)))
  returning id into v_log;

  perform public._add_report_evidence(p_report, v_log, 'update', p_media);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          'Update on ' || v_report.tracking_id || ': '
          || coalesce(v_body, 'the barangay added photos.'));

  return v_log;
end $$;


--
-- Name: FUNCTION admin_barangay_update(p_report uuid, p_body text, p_media jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_barangay_update(p_report uuid, p_body text, p_media jsonb) IS 'The admin posts an update, with up to 6 photos, to a complaint''s timeline and its resident, with or without a tanod on it (0079).';


--
-- Name: admin_candidates(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_candidates(p_search text DEFAULT NULL::text) RETURNS TABLE(id uuid, full_name text, email text, role public.user_role, mobile_number text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select u.id, u.full_name, u.email, u.role, u.mobile_number
    from public.users u
   where u.verification_status = 'verified'
     and not u.is_suspended
     and u.role <> 'admin'
     and (p_search is null or trim(p_search) = ''
          or u.full_name ilike '%' || trim(p_search) || '%'
          or u.email     ilike '%' || trim(p_search) || '%')
   order by u.full_name
   limit 25
$$;


--
-- Name: FUNCTION admin_candidates(p_search text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_candidates(p_search text) IS 'Verified, unsuspended, non-admin accounts. Verified means the barangay confirmed they live in 183.';


--
-- Name: admin_dispatch(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_dispatch(p_report uuid, p_tanod uuid, p_instructions text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report   public.reports%rowtype;
  v_tanod    public.users%rowtype;
  v_busy     text;
  v_dispatch uuid;
  v_metres   double precision;
  v_note     text := nullif(trim(coalesce(p_instructions, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may assign a dispatch manually';
  end if;

  select * into v_report from public.reports where id = p_report and deleted_at is null;
  if not found then
    raise exception 'No such report';
  end if;

  -- Set, not necessarily future: a reroute of an overdue complaint comes
  -- through here too. The assign form itself only takes a future date.
  if v_report.due_at is null then
    raise exception 'Set a target resolution date before dispatching';
  end if;

  if v_note is null then
    raise exception 'Write instructions for the tanod before dispatching';
  end if;

  select * into v_tanod from public.users where id = p_tanod;
  if not found or v_tanod.role <> 'tanod' then
    raise exception 'That account is not a tanod';
  end if;

  if not v_tanod.is_dispatchable then
    raise exception '% is not available for dispatch (duty status: %)',
      v_tanod.full_name, coalesce(v_tanod.duty_status::text, 'not set');
  end if;

  select case when count(*) >= public.tanod_dispatch_cap() then max(r.subject) end into v_busy
    from public.dispatches d
    join public.reports r on r.id = d.report_id
   where d.tanod_id = p_tanod and d.state in ('assigned', 'accepted');

  if v_busy is not null then
    raise exception
      '% already has the most dispatches a tanod can hold at once. Choose another available tanod.',
      v_tanod.full_name;
  end if;

  select st_distance(v_tanod.last_geom, v_report.geom) into v_metres;

  insert into public.dispatches (report_id, tanod_id, assigned_by, admin_instructions)
  values (p_report, p_tanod, auth.uid(), v_note)
  returning id into v_dispatch;

  update public.reports
     set status = 'assigned', awaiting_unit_since = null
   where id = p_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, 'assigned',
          case when v_metres is null
            then format('Manually assigned to %s by admin', v_tanod.full_name)
            else format('Manually assigned to %s by admin (%s m from the incident)',
                        v_tanod.full_name, round(v_metres))
          end);

  insert into public.notifications (user_id, report_id, kind, message)
  values (p_tanod, p_report, 'assignment',
          format('Assigned by the barangay admin: %s', v_report.subject));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'assignment',
          format('A tanod has been dispatched to your report %s.', v_report.tracking_id));

  return v_dispatch;
end $$;


--
-- Name: admin_reroute_dispatch(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reroute_dispatch(p_dispatch uuid, p_reason text, p_to uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_d      public.dispatches%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_tick   text;
  v_next   uuid;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may reroute a dispatch';
  end if;
  if v_reason is null then
    raise exception 'A reason is required to reroute a dispatch';
  end if;

  select * into v_d from public.dispatches
   where id = p_dispatch and state in ('assigned', 'accepted')
   for update;
  if not found then
    raise exception 'That dispatch is no longer active';
  end if;
  if p_to is not null and p_to = v_d.tanod_id then
    raise exception 'That tanod already has this dispatch';
  end if;

  update public.dispatches
     set state = 'rerouted', rerouted_at = now(),
         reroute_reason = 'By the barangay: ' || v_reason, rerouted_to = p_to
   where id = p_dispatch;

  select tracking_id into v_tick from public.reports where id = v_d.report_id;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (v_d.report_id, auth.uid(), 'assigned', 'assigned',
          'Rerouted by the barangay: ' || v_reason);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_d.tanod_id, v_d.report_id, 'reroute',
          format('The barangay moved %s to another tanod: %s', v_tick, v_reason));

  if p_to is not null then
    -- admin_dispatch checks the new tanod (on duty, not busy), sets the
    -- report to assigned, and notifies them and the resident. Any
    -- refusal there rolls this whole call back.
    v_next := public.admin_dispatch(v_d.report_id, p_to,
                                    'Rerouted by the barangay: ' || v_reason);
  else
    v_next := public.redispatch_report(v_d.report_id,
                                       'rerouted by the barangay: ' || v_reason);
  end if;

  return v_next;
end $$;


--
-- Name: FUNCTION admin_reroute_dispatch(p_dispatch uuid, p_reason text, p_to uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_reroute_dispatch(p_dispatch uuid, p_reason text, p_to uuid) IS 'An admin moves a live dispatch to another tanod (p_to) or back to the system''s nearest-tanod routing (p_to null). Reason required. 0070.';


--
-- Name: admin_reset_password(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reset_password(p_user uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'auth'
    AS $$
declare
  v_user    public.users%rowtype;
  v_temp    text;
  v_alpha   text := 'ABCDEFGHJKLMNPQRSTUVWXYZ';   -- no I or O
  v_digit   text := '23456789';                    -- no 0 or 1
  v_changed integer;
  i         integer;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may reset a password';
  end if;

  select * into v_user from public.users where id = p_user for update;
  if not found then
    raise exception 'No such account';
  end if;

  if v_user.role = 'admin' then
    raise exception 'Administrator passwords are not reset through this path';
  end if;

  if v_user.is_suspended then
    raise exception 'This account is suspended. Lift the suspension first.';
  end if;

  -- Checked before anything is generated or written. An account with no
  -- sign-in record cannot be given a password, and the honest answer is
  -- that it has to be registered through the app first.
  if not exists (select 1 from auth.users where id = p_user) then
    raise exception
      'This account has never signed in and has no credential to reset. '
      'It must be registered through the app.';
  end if;

  v_temp := '';
  for i in 1..4 loop
    v_temp := v_temp || substr(v_alpha, 1 + floor(random() * length(v_alpha))::int, 1);
  end loop;
  v_temp := v_temp || '-';
  for i in 1..4 loop
    v_temp := v_temp || substr(v_digit, 1 + floor(random() * length(v_digit))::int, 1);
  end loop;
  v_temp := v_temp || '-';
  for i in 1..3 loop
    v_temp := v_temp || substr(v_alpha, 1 + floor(random() * length(v_alpha))::int, 1);
  end loop;

  update auth.users
     set encrypted_password = extensions.crypt(v_temp, extensions.gen_salt('bf')),
         updated_at         = now()
   where id = p_user;

  -- Not `if not found`. FOUND carries over from the SELECT above and
  -- reports true regardless of what this UPDATE did — which is exactly
  -- how 0028 handed out a password for an account it never touched.
  get diagnostics v_changed = row_count;
  if v_changed <> 1 then
    raise exception
      'The password was not changed (% rows affected). Nothing has been '
      'issued.', v_changed;
  end if;

  update public.users
     set must_change_password = true
   where id = p_user;

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (p_user, auth.uid(), 'password_reset',
          'Temporary password issued in person');

  return v_temp;
end $$;


--
-- Name: FUNCTION admin_reset_password(p_user uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_reset_password(p_user uuid) IS 'Issues a temporary password for a resident or tanod and returns it to the calling administrator once. Never stored in plaintext.';


--
-- Name: admin_set_status(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_status(p_report uuid, p_status text, p_remark text DEFAULT NULL::text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_new    report_status;
  v_remark text := nullif(trim(coalesce(p_remark, '')), '');
  v_log    uuid;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may change a complaint''s status';
  end if;
  if p_status not in ('in_progress', 'offline_investigation', 'resolved') then
    raise exception 'Choose In Progress, Offline Investigation or Resolved';
  end if;
  v_new := p_status::report_status;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if v_report.status in ('closed', 'archived', 'rejected', 'cancelled', 'pending_review') then
    raise exception 'This complaint''s status cannot be changed here';
  end if;
  if v_report.status = v_new then
    raise exception 'The complaint is already %', replace(p_status, '_', ' ');
  end if;

  if v_new = 'resolved' then
    update public.dispatches
       set state = 'rerouted', rerouted_at = now(), reroute_reason = 'Resolved by the barangay'
     where report_id = p_report and state in ('assigned', 'accepted');
    update public.reports
       set status = 'resolved', resolved_at = now(), resolution_submitted_at = null
     where id = p_report;
  else
    update public.reports set status = v_new where id = p_report;
  end if;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, v_new,
          coalesce(v_remark, case v_new
            when 'in_progress' then 'Status set to In Progress by the barangay.'
            when 'offline_investigation' then 'Status set to Offline Investigation by the barangay.'
            else 'Marked resolved by the barangay.' end))
  returning id into v_log;

  perform public._add_report_evidence(p_report, v_log,
          case when v_new = 'resolved' then 'resolution' else 'update' end, p_media);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          case v_new
            when 'in_progress' then 'Your complaint ' || v_report.tracking_id || ' is in progress.'
            when 'offline_investigation' then 'Your complaint ' || v_report.tracking_id || ' is under offline investigation by the barangay.'
            else 'Your complaint ' || v_report.tracking_id || ' has been resolved.' end
          || coalesce(' ' || v_remark, ''));
end $$;


--
-- Name: admin_update_user(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_user(p_user uuid, p_full_name text, p_email text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_user  public.users%rowtype;
  v_name  text := nullif(regexp_replace(trim(coalesce(p_full_name, '')), '\s+', ' ', 'g'), '');
  v_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may correct a profile';
  end if;
  select * into v_user from public.users where id = p_user for update;
  if not found then
    raise exception 'No such account';
  end if;
  if v_user.role = 'admin' then
    raise exception 'Administrators edit their own profile under Edit Profile';
  end if;
  if v_name is null then
    raise exception 'Enter the full name';
  end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'That email address does not look right';
  end if;
  if v_email is not null and exists (select 1 from public.users
                                      where lower(email) = v_email and id <> p_user) then
    raise exception 'Another account already uses that email address';
  end if;

  update public.users
     set full_name = v_name,
         email = coalesce(v_email, email)
   where id = p_user;

  insert into public.notifications (user_id, report_id, kind, message)
  values (p_user, null, 'verification',
          'The barangay corrected your profile details. Check them under Edit Profile.');
end $_$;


--
-- Name: appeal_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.appeal_report(p_report uuid, p_remark text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_remark text := nullif(trim(coalesce(p_remark, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may act on an appeal';
  end if;

  select * into v_report
    from public.reports
   where id = p_report and deleted_at is null
     for update;

  if not found then
    raise exception 'No such report';
  end if;

  if v_report.status <> 'rejected' then
    raise exception 'Only a rejected complaint can be reinstated on appeal';
  end if;

  -- 0071: no fresh policy window; the admin sets the date when assigning.
  update public.reports
     set status      = 'validated',
         appealed_at = now(),
         due_at      = null
   where id = p_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), 'rejected', 'validated',
          coalesce(v_remark, 'Appeal granted: reinstated for review.'));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          format('Your appeal for %s was granted. It is back with the barangay.',
                 v_report.tracking_id));
end $$;


--
-- Name: FUNCTION appeal_report(p_report uuid, p_remark text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.appeal_report(p_report uuid, p_remark text) IS 'Grants a resident appeal: rejected back to validated, marks appealed_at, clears the target date for the admin to set again (0071), logs and notifies the resident. Admin only.';


--
-- Name: approve_escalation(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_escalation(p_request uuid, p_office text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_r public.escalation_requests%rowtype;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may decide an escalation request';
  end if;
  select * into v_r from public.escalation_requests where id = p_request for update;
  if not found or v_r.status <> 'pending' then
    raise exception 'That request has already been decided';
  end if;

  perform public.refer_report(v_r.report_id, p_office, p_note);

  update public.escalation_requests
     set decision_note = nullif(trim(coalesce(p_note, '')), '')
   where id = p_request;

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_r.requested_by, v_r.report_id, 'status_change',
          'Your escalation request was approved: escalated to the ' || trim(p_office) || '.');
end $$;


--
-- Name: approve_resolution(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_resolution(p_report uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_d      public.dispatches%rowtype;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may approve a resolution';
  end if;
  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if v_report.resolution_submitted_at is null or v_report.status = 'resolved' then
    raise exception 'There is no resolution waiting for approval';
  end if;

  select * into v_d from public.dispatches
   where report_id = p_report and state = 'resolved'
   order by resolved_at desc nulls last limit 1;

  update public.reports
     set status = 'resolved', resolved_at = now(), resolution_submitted_at = null
   where id = p_report;

  -- The tanod's own words stay the resolution note the resident reads.
  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, 'resolved',
          coalesce(nullif(trim(v_d.field_report_text), ''), 'Resolution approved by the barangay.'));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          'Your complaint ' || v_report.tracking_id || ' has been resolved.');

  if v_d.tanod_id is not null then
    insert into public.notifications (user_id, report_id, kind, message)
    values (v_d.tanod_id, p_report, 'status_change',
            'The barangay approved your resolution of ' || v_report.tracking_id || '.');
  end if;
end $$;


--
-- Name: assert_not_client(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_not_client(p_what text) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if current_user in ('authenticated', 'anon') then
    raise exception '% may not be called directly. Administrators use admin_dispatch().', p_what;
  end if;
end $$;


--
-- Name: assign_tracking_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_tracking_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_n bigint;
begin
  if new.tracking_id is null then
    v_n := nextval('public.report_seq');
    new.tracking_id := 'BRG-' || to_char(now(), 'YYYY') || '-' ||
                       lpad(v_n::text, greatest(4, length(v_n::text)), '0');
  end if;
  return new;
end $$;


--
-- Name: assignable_tanods(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assignable_tanods(p_report uuid) RETURNS TABLE(tanod_id uuid, full_name text, metres double precision, location_fresh boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select u.id, u.full_name,
         st_distance(u.last_geom, r.geom),
         public.location_is_fresh(u.last_location_at)
    from public.reports r
    cross join public.users u
   where r.id = p_report
     and u.is_dispatchable
     and (select count(*) from public.dispatches d
           where d.tanod_id = u.id and d.state in ('assigned', 'accepted')) < public.tanod_dispatch_cap()
   order by st_distance(u.last_geom, r.geom) nulls last, u.full_name
$$;


--
-- Name: audit_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_integrity() RETURNS TABLE(scope text, entries bigint, broken bigint, head_hash text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_broken bigint := 0;
  v_bad    bigint;
  r        record;
begin
  for r in select distinct report_id from public.status_logs loop
    select count(*) filter (where not v.intact) into v_bad
      from public.verify_report_trail(r.report_id) v;
    v_broken := v_broken + coalesce(v_bad, 0);
  end loop;

  scope   := 'Complaint trail';
  select count(*) into entries from public.status_logs;
  broken  := v_broken;
  select entry_hash into head_hash from public.status_logs order by created_at desc, id desc limit 1;
  return next;

  scope   := 'Account changes';
  select count(*) into entries from public.account_audit;
  broken  := 0;
  select entry_hash into head_hash from public.account_audit order by created_at desc, id desc limit 1;
  return next;
end $$;


--
-- Name: FUNCTION audit_integrity(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.audit_integrity() IS 'Summary for the turnover pack. head_hash is the value worth printing on the monthly report — an outside copy is what makes a rebuilt chain detectable.';


--
-- Name: auth_email_for(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_email_for(p_mobile text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'extensions'
    AS $$
  select regexp_replace(p_mobile, '[^0-9]', '', 'g')
         || '@auth.smartsumbong.local'
$$;


--
-- Name: FUNCTION auth_email_for(p_mobile text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auth_email_for(p_mobile text) IS 'The synthetic Supabase Auth address for a mobile number. Digits only, so +639171234567 and 09171234567 must already have been normalised to the same form by the client before they reach here.';


--
-- Name: auto_dispatch(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_dispatch(p_report uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report     public.reports%rowtype;
  v_tanod      uuid;
  v_tanod_name text;
  v_metres     double precision;
  v_dispatch   uuid;
  v_system     uuid;
  v_last       text;
begin
  select * into v_report from public.reports where id = p_report;
  if not found then
    raise exception 'No such report';
  end if;

  -- NEW (0064): the newest remark on this report's trail, so a retry
  -- that changes nothing doesn't log the same line again.
  select remark into v_last
    from public.status_logs
   where report_id = p_report
   order by created_at desc
   limit 1;

  -- Out of jurisdiction: refer, do not dispatch.
  if not public.is_within_barangay(v_report.latitude, v_report.longitude) then
    update public.reports
       set escalation_level = greatest(escalation_level, 1),
           escalated_at = coalesce(escalated_at, now())
     where id = p_report;

    if v_last is distinct from 'Outside Barangay 183 — referred to city services' then
      insert into public.status_logs (report_id, changed_by, old_status, new_status,
                                      remark, is_system)
      values (p_report, v_report.resident_id, v_report.status, v_report.status,
              'Outside Barangay 183 — referred to city services', true);
    end if;
    return null;
  end if;

  select t.tanod_id, t.full_name, t.metres into v_tanod, v_tanod_name, v_metres
    from public.nearest_available_tanod(p_report) t limit 1;

  if v_tanod is null then
    if v_last is distinct from
         'No tanod available for automatic dispatch — awaiting manual assignment' then
      insert into public.status_logs (report_id, changed_by, old_status, new_status,
                                      remark, is_system)
      values (p_report, v_report.resident_id, v_report.status, v_report.status,
              'No tanod available for automatic dispatch — awaiting manual assignment', true);
    end if;
    return null;
  end if;

  -- assigned_by records the system, using the report's own admin-less
  -- path: attributed to the nearest tanod's own id would be wrong, so
  -- the first admin on record stands as the dispatching authority.
  select id into v_system from public.users where role = 'admin' order by created_at limit 1;

  insert into public.dispatches (report_id, tanod_id, assigned_by, admin_instructions)
  values (p_report, v_tanod, coalesce(v_system, v_tanod),
          case when v_metres is null
               then 'Automatic dispatch — on-duty unit; no location shared yet.'
               else format('Automatic dispatch — nearest available unit, %s m from the incident.',
                           round(v_metres)) end)
  returning id into v_dispatch;

  update public.reports set status = 'assigned' where id = p_report;

  -- NEW (0047): names the tanod, same pattern admin_dispatch already
  -- uses ("Manually assigned to %s by admin ...") -- the resident's
  -- timeline now answers "who is coming", not just "how far".
  insert into public.status_logs (report_id, changed_by, old_status, new_status,
                                  remark, is_system)
  values (p_report, coalesce(v_system, v_tanod), v_report.status, 'assigned',
          case when v_metres is null
               then format('Auto-dispatched to %s', v_tanod_name)
               else format('Auto-dispatched to %s (%s m away)', v_tanod_name, round(v_metres)) end, true);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_tanod, p_report, 'assignment',
          format('New dispatch: %s', v_report.subject));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'assignment',
          format('A tanod has been dispatched to your report %s.', v_report.tracking_id));

  return v_dispatch;
end $$;


--
-- Name: FUNCTION auto_dispatch(p_report uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_dispatch(p_report uuid) IS 'INTERNAL. Called by the on-file trigger, redispatch_report and the sweeps. Not callable by clients — administrators use admin_dispatch(). See 0016.';


--
-- Name: cancel_admin_handover(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_admin_handover() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may cancel a handover';
  end if;

  update public.users
     set admin_handover_until        = null,
         admin_handover_role         = null,
         admin_handover_successor_id = null
   where id = auth.uid();
end $$;


--
-- Name: FUNCTION cancel_admin_handover(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancel_admin_handover() IS 'Ends the caller''s own in-progress handover window immediately. Does not touch the successor''s admin access either way -- they keep it.';


--
-- Name: cancel_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_report(p_report uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_old    report_status;
  v_owner  uuid;
begin
  -- No longer protected by reports_resident_read as invoker would be —
  -- SECURITY DEFINER bypasses RLS, so the ownership check right below is
  -- now the only thing standing between a resident and someone else's
  -- report. It was already here; it is now load-bearing rather than
  -- redundant.
  select status, resident_id
    into v_old, v_owner
    from public.reports
   where id = p_report and deleted_at is null;

  if v_old is null then
    raise exception 'Report not found';
  end if;

  if v_owner is distinct from auth.uid() then
    raise exception 'Only the resident who filed a report may cancel it';
  end if;

  if v_old not in ('pending_review', 'validated') then
    raise exception
      'This report can no longer be cancelled because the barangay has '
      'already started working on it';
  end if;

  update public.reports
     set status = 'cancelled',
         closed_at = now()
   where id = p_report;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark)
  values
    (p_report, auth.uid(), v_old, 'cancelled',
     coalesce(nullif(trim(p_reason), ''), 'Withdrawn by the resident'));
end $$;


--
-- Name: FUNCTION cancel_report(p_report uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancel_report(p_report uuid, p_reason text) IS 'Lets the resident who filed a complaint withdraw it, but only before anyone is working on it — pending_review or validated. SECURITY DEFINER (0030): the reports UPDATE and status_logs INSERT both need privileges RLS gives only admins and the DEFINER transition functions (see status_logs_insert in 0003) — the explicit ownership check below is what makes that safe, not RLS.';


--
-- Name: chain_account_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chain_account_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_prev text;
begin
  select entry_hash into v_prev
    from public.account_audit
   order by created_at desc, id desc
   limit 1;

  new.prev_hash  := coalesce(v_prev, repeat('0', 64));
  new.entry_hash := encode(
    extensions.digest(new.prev_hash || '|' || public.account_audit_fingerprint(new), 'sha256'), 'hex');
  return new;
end $$;


--
-- Name: chain_status_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chain_status_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_prev text;
begin
  -- One writer per complaint trail at a time.
  perform pg_advisory_xact_lock(hashtextextended('status_logs:' || new.report_id::text, 0));

  -- The head: the newest entry no other entry links to yet.
  select s.entry_hash into v_prev
    from public.status_logs s
   where s.report_id = new.report_id
     and not exists (select 1 from public.status_logs t
                      where t.report_id = s.report_id and t.prev_hash = s.entry_hash)
   order by s.created_at desc, s.id desc
   limit 1;

  new.prev_hash  := coalesce(v_prev, repeat('0', 64));
  new.entry_hash := encode(
    extensions.digest(new.prev_hash || '|' || public.status_log_fingerprint(new), 'sha256'), 'hex');
  return new;
end $$;


--
-- Name: check_login_lockout(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_login_lockout(p_mobile text) RETURNS TABLE(locked boolean, seconds_remaining integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_locked_until timestamptz;
begin
  if p_mobile is null or p_mobile !~ '^\+63[0-9]{10}$' then
    return query select false, 0;
    return;
  end if;

  select la.locked_until into v_locked_until
    from public.login_attempts la
   where la.mobile_number = p_mobile;

  if v_locked_until is not null and v_locked_until > now() then
    return query select true,
      greatest(0, ceil(extract(epoch from (v_locked_until - now())))::int);
  else
    return query select false, 0;
  end if;
end $_$;


--
-- Name: FUNCTION check_login_lockout(p_mobile text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_login_lockout(p_mobile text) IS 'Call before attempting sign-in. True + seconds remaining if this number is currently locked; false otherwise. Malformed input is treated as never-locked rather than raising, since the caller is about to fail its own normalisation check anyway.';


--
-- Name: check_system_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_system_health() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_keep  text[] := '{}';
  r       record;
  v_bytes bigint := pg_database_size(current_database());
  v_limit bigint := 500 * 1024 * 1024;  -- Supabase free plan
  v_stuck integer;
  v_fn    integer;
begin
  -- Scheduled jobs that failed in the last day, by name.
  if to_regclass('cron.job_run_details') is not null then
    for r in execute $q$
      select j.jobname, count(*) as n, max(d.return_message) as why
        from cron.job_run_details d join cron.job j on j.jobid = d.jobid
       where d.status = 'failed' and d.start_time > now() - interval '1 day'
       group by j.jobname $q$
    loop
      v_keep := v_keep || ('job:' || r.jobname);
      perform public._raise_alert('job:' || r.jobname, format(
        'the scheduled job %s failed %s time%s in the last day (%s).',
        r.jobname, r.n, case when r.n = 1 then '' else 's' end, left(coalesce(r.why, 'no message'), 160)));
    end loop;
  end if;
  perform public._clear_alerts_except('job:', v_keep);

  -- Database size against the free plan.
  if v_bytes > v_limit * 0.8 then
    perform public._raise_alert('db_size', format(
      'the database is %s of the free plan''s 500 MB. Archive old records or move to a paid plan.',
      pg_size_pretty(v_bytes)));
  else
    perform public._clear_alerts_except('db_size', '{}');
  end if;

  -- Identity photos that should have been deleted a week ago.
  select count(*) into v_stuck from public.media_trash
   where queued_at < now() - interval '14 days' and not public.identity_media_in_use(url);
  if v_stuck > 0 then
    perform public._raise_alert('media_cleanup', format(
      '%s identity photo%s should have been deleted from Cloudinary by now. Check that media-cleanup is deployed and its Vault secrets are set.',
      v_stuck, case when v_stuck = 1 then '' else 's' end));
  else
    perform public._clear_alerts_except('media_cleanup', '{}');
  end if;

  -- Edge Function failures in the last day.
  select coalesce(sum(count), 0) into v_fn from public.portal_errors
   where source = 'function' and last_seen > now() - interval '1 day';
  if v_fn > 0 then
    perform public._raise_alert('functions', format(
      'Edge Functions failed %s time%s in the last day. See Settings -> System status -> Recent errors.',
      v_fn, case when v_fn = 1 then '' else 's' end));
  else
    perform public._clear_alerts_except('functions', '{}');
  end if;
end $_$;


--
-- Name: clear_login_attempts(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_login_attempts(p_mobile text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- Only your own number, and only once signed in: the app calls this
  -- right after a successful sign-in, never before.
  delete from public.login_attempts la
   using public.users u
   where u.id = (select auth.uid())
     and u.mobile_number = p_mobile
     and la.mobile_number = p_mobile;
end $$;


--
-- Name: FUNCTION clear_login_attempts(p_mobile text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.clear_login_attempts(p_mobile text) IS 'Call once sign-in succeeds. 0114: clears only the signed-in caller''s own number; anyone else''s, or a call made while signed out, does nothing.';


--
-- Name: clear_password_change_flag(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_password_change_flag() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;

  update public.users
     set must_change_password = false
   where id = auth.uid();
end $$;


--
-- Name: confirm_synthetic_auth_email(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_synthetic_auth_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- Only the derived domain. A real address created for an admin by
  -- hand keeps whatever confirmation flow it came with.
  if new.email like '%@auth.smartsumbong.local'
     and new.email_confirmed_at is null then
    new.email_confirmed_at := now();
  end if;
  return new;
end $$;


--
-- Name: FUNCTION confirm_synthetic_auth_email(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_synthetic_auth_email() IS 'Marks derived auth addresses confirmed at creation. They cannot receive mail — .local is unresolvable — so an unconfirmed one is an account that can never sign in. Identity is verified by the barangay admin against ID and selfie, not by proving control of a mailbox that does not exist.';


--
-- Name: create_admin_account(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_admin_account(p_email text, p_full_name text, p_mobile text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'auth'
    AS $_$
declare
  v_email  text := lower(trim(coalesce(p_email, '')));
  v_name   text := trim(coalesce(p_full_name, ''));
  v_mobile text := trim(coalesce(p_mobile, ''));
  v_id     uuid := gen_random_uuid();
  v_temp   text := public._temp_password();
  v_comma  int;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may add an administrator';
  end if;
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'Enter a valid email address';
  end if;
  v_comma := position(',' in v_name);
  if v_comma <= 1 or length(trim(substring(v_name from v_comma + 1))) = 0 then
    raise exception 'Write the name as Last Name, First Name';
  end if;
  if v_mobile ~ '^09[0-9]{9}$' then
    v_mobile := '+63' || substr(v_mobile, 2);
  end if;
  if v_mobile !~ '^\+639[0-9]{9}$' then
    raise exception 'Enter the mobile number as 09XXXXXXXXX';
  end if;
  if exists (select 1 from auth.users where lower(email) = v_email)
     or exists (select 1 from public.users where lower(email) = v_email) then
    raise exception 'That email already has an account';
  end if;
  if exists (select 1 from public.users where mobile_number = v_mobile) then
    raise exception 'That mobile number already has an account';
  end if;

  perform set_config('smartsumbong.provisioning_admin', 'on', true);

  insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
                          raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
                          confirmation_token, recovery_token, email_change_token_new, email_change)
  values ('00000000-0000-0000-0000-000000000000', v_id, 'authenticated', 'authenticated', v_email,
          extensions.crypt(v_temp, extensions.gen_salt('bf')), now(),
          '{"provider":"email","providers":["email"]}'::jsonb,
          jsonb_build_object('full_name', v_name), now(), now(), '', '', '', '');

  insert into auth.identities (id, provider_id, user_id, identity_data, provider, created_at, updated_at)
  values (gen_random_uuid(), v_id::text, v_id,
          jsonb_build_object('sub', v_id::text, 'email', v_email, 'email_verified', true),
          'email', now(), now());

  perform set_config('smartsumbong.provisioning_admin', 'off', true);

  insert into public.users (id, full_name, email, mobile_number, role,
                            verification_status, verified_at, verified_by, must_change_password)
  values (v_id, v_name, v_email, v_mobile, 'admin', 'verified', now(), auth.uid(), true);

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (v_id, auth.uid(), 'admin_created', 'Administrator account created with a temporary password');

  return v_temp;
end $_$;


--
-- Name: dashboard_metrics(timestamp with time zone, timestamp with time zone, public.complaint_category); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_metrics(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category DEFAULT NULL::public.complaint_category) RETURNS json
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_out json;
begin
  if p_from is null or p_to is null or p_to <= p_from then
    raise exception 'Invalid reporting period';
  end if;

  with scoped as (
    select r.*,
           -- "Finished" covers resolved and closed alike: a complaint
           -- the barangay has dealt with, whether or not the resident
           -- has since confirmed it.
           (r.status in ('resolved', 'closed', 'archived'))         as is_done,
           coalesce(r.resolved_at, r.closed_at)                     as finished_at
      from public.reports r
     where r.deleted_at is null
       and r.created_at >= p_from
       and r.created_at <  p_to
  ),
  classified as (
    select s.*,
           case
             -- Sent to an outside office (0072): neither resolved here
             -- nor still open.
             when s.referred_to is not null                then 'referred'
             -- Finished after the deadline it was given.
             when s.is_done and s.due_at is not null
                  and s.finished_at > s.due_at              then 'late'
             -- Finished in time, or finished with no deadline set.
             when s.is_done                                then 'done'
             -- Still open and the deadline has passed.
             when s.due_at is not null and now() > s.due_at then 'overdue'
             -- Still open, still inside the window. Rejected complaints
             -- are not work in progress and are counted separately.
             when s.status = 'rejected'                    then 'rejected'
             else                                               'processing'
           end as bucket
      from scoped s
  )
  select json_build_object(

    'period', json_build_object('from', p_from, 'to', p_to),

    'total', (select count(*) from scoped),

    -- Reports filed per calendar day, Manila time, with empty days
    -- present as zeroes so the line does not lie by skipping them.
    'daily', (
      select coalesce(json_agg(json_build_object(
               'day',   to_char(d.day, 'YYYY-MM-DD'),
               'label', to_char(d.day, 'FMDD'),
               'filed', coalesce(c.n, 0)) order by d.day), '[]'::json)
        from generate_series(
               (p_from at time zone 'Asia/Manila')::date,
               (p_to   at time zone 'Asia/Manila')::date - 1,
               interval '1 day') as d(day)
        left join (
          select (created_at at time zone 'Asia/Manila')::date as day, count(*) as n
            from scoped group by 1) c on c.day = d.day::date
    ),

    'resolution_status', (
      select json_build_object(
               'done',       count(*) filter (where bucket = 'done'),
               'overdue',    count(*) filter (where bucket = 'overdue'),
               'late',       count(*) filter (where bucket = 'late'),
               'processing', count(*) filter (where bucket = 'processing'),
               'rejected',   count(*) filter (where bucket = 'rejected'),
               'referred',   count(*) filter (where bucket = 'referred'))
        from classified
    ),

    'categories', (
      select coalesce(json_agg(json_build_object(
               'category', category, 'n', n) order by n desc, category), '[]'::json)
        from (select category::text as category, count(*) as n
                from scoped group by 1) t
    ),

    -- The three counters. Resolved and escalated are counts; the third
    -- is every complaint whose deadline has passed with nobody having
    -- finished it, which is the number an admin actually needs to see.
    'tiles', (
      select json_build_object(
               'resolved',  count(*) filter (where bucket in ('done', 'late')),
               -- 0072: escalated now means referred outside the barangay;
               -- the key keeps its name for the dashboard's sake.
               'escalated', count(*) filter (where bucket = 'referred'),
               'overdue',   count(*) filter (where bucket = 'overdue'))
        from classified
    ),

    -- Resolution efficiency: for each day, the mean hours between filing
    -- and finishing for the complaints finished that day, against the
    -- policy window they were held to. Two lines, one chart — "we took
    -- 31 hours" means nothing without "we were allowed 48". p_category
    -- (0056), when given, narrows this one chart only — every other key
    -- above is computed from the unfiltered `scoped`/`classified` CTEs.
    'efficiency', (
      select coalesce(json_agg(json_build_object(
               'day',     to_char(d.day, 'YYYY-MM-DD'),
               'label',   to_char(d.day, 'FMDD'),
               'actual',  e.avg_hours,
               'allowed', e.avg_target,
               'n',       coalesce(e.n, 0)) order by d.day), '[]'::json)
        from generate_series(
               (p_from at time zone 'Asia/Manila')::date,
               (p_to   at time zone 'Asia/Manila')::date - 1,
               interval '1 day') as d(day)
        left join (
          select (c.finished_at at time zone 'Asia/Manila')::date as day,
                 count(*) as n,
                 round(avg(extract(epoch from (c.finished_at - c.created_at)) / 3600)::numeric, 1)
                   as avg_hours,
                 round(avg(p.resolution_hours)::numeric, 1) as avg_target
            from classified c
            join public.sla_policies p on p.category = c.category
           where c.finished_at is not null
             and (p_category is null or c.category = p_category)
           group by 1) e on e.day = d.day::date
    )

  ) into v_out;

  return v_out;
end $$;


--
-- Name: FUNCTION dashboard_metrics(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dashboard_metrics(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category) IS 'Every figure on the analytics dashboard in one pass. Runs with the caller''s rights, so RLS decides what is counted. p_category (0056) narrows the efficiency chart only.';


--
-- Name: decide_profile_request(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_profile_request(p_request uuid, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  r      public.profile_requests%rowtype;
  v_note text := nullif(trim(coalesce(p_note, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may decide a profile request';
  end if;
  select * into r from public.profile_requests where id = p_request for update;
  if not found then
    raise exception 'No such request';
  end if;
  if r.status <> 'pending' then
    raise exception 'This request has already been decided';
  end if;
  if not p_approve and v_note is null then
    raise exception 'Give a reason for declining; the person sees it';
  end if;

  if p_approve then
    if r.kind = 'full_name' then
      update public.users set full_name = r.new_full_name where id = r.user_id;
    else
      update public.users set id_image_url = r.id_image_url, id_type = r.id_type where id = r.user_id;
    end if;
  end if;

  update public.profile_requests
     set status = case when p_approve then 'approved' else 'declined' end,
         decided_by = auth.uid(), decided_at = now(), decision_note = v_note
   where id = p_request;

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (r.user_id, auth.uid(),
          case r.kind when 'full_name' then 'name_change_' else 'id_reupload_' end || case when p_approve then 'approved' else 'declined' end,
          case r.kind when 'full_name' then 'Name change to ' || r.new_full_name else 'New ID photo' end
          || case when p_approve then ' approved' else ' declined' end || coalesce(': ' || v_note, ''));

  insert into public.notifications (user_id, kind, message)
  values (r.user_id, 'status_change',
          case r.kind when 'full_name' then 'Your name change' else 'Your new ID photo' end
          || case when p_approve then ' was approved by the barangay.' else ' was not approved' || coalesce(': ' || v_note, '.') end);
end $$;


--
-- Name: deny_escalation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deny_escalation(p_request uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_r      public.escalation_requests%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_tick   text;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may decide an escalation request';
  end if;
  if v_reason is null then
    raise exception 'A reason is required to deny an escalation request';
  end if;
  select * into v_r from public.escalation_requests where id = p_request for update;
  if not found or v_r.status <> 'pending' then
    raise exception 'That request has already been decided';
  end if;

  update public.escalation_requests
     set status = 'denied', decided_by = auth.uid(), decided_at = now(),
         decision_note = v_reason
   where id = p_request;

  select tracking_id into v_tick from public.reports where id = v_r.report_id;

  -- The complaint stays with the barangay, in progress.
  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  select v_r.report_id, auth.uid(), r.status, r.status,
         'Escalation request denied: ' || v_reason
    from public.reports r where r.id = v_r.report_id;

  if v_r.dispatch_id is not null then
    insert into public.dispatch_updates (dispatch_id, author_id, kind, body)
    values (v_r.dispatch_id, auth.uid(), 'note', 'Escalation request denied: ' || v_reason);
  end if;

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_r.requested_by, v_r.report_id, 'status_change',
          'Your escalation request for ' || v_tick || ' was denied: ' || left(v_reason, 140));
end $$;


--
-- Name: dispatch_on_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_on_file() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_auto boolean;
begin
  select auto_dispatch_on_file into v_auto
    from public.sla_policies where category = new.category;

  if coalesce(v_auto, false) then
    perform public.auto_dispatch(new.id);
  end if;

  return null;
end $$;


--
-- Name: FUNCTION dispatch_on_file(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dispatch_on_file() IS 'Fires at COMMIT, not at INSERT, so that a complaint filed through file_report() has its photos attached before a tanod is dispatched to it.';


--
-- Name: display_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.display_name(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select case when position(',' in coalesce(p_name, '')) > 1
              then trim(substring(p_name from position(',' in p_name) + 1)) || ' ' || trim(split_part(p_name, ',', 1))
              else p_name end
$$;


--
-- Name: end_sessions_on_access_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_sessions_on_access_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
  delete from auth.sessions where user_id = new.id;
  return new;
end $$;


--
-- Name: FUNCTION end_sessions_on_access_change(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.end_sessions_on_access_change() IS '0115: ends every session of a user whose password was reset by the barangay, or who was suspended or retired.';


--
-- Name: enforce_daily_report_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_daily_report_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_limit   integer;
  v_paused  boolean;
  v_message text;
begin
  if new.resident_id is null or new.resident_id is distinct from (select auth.uid()) then
    return new;  -- not a resident filing for themselves (jobs, tests as postgres)
  end if;
  select max_reports_per_day, filing_paused, filing_paused_message
    into v_limit, v_paused, v_message
    from public.operational_settings where id = 1;
  if coalesce(v_paused, false) then
    raise exception '%', coalesce(nullif(trim(v_message), ''),
      'Filing new reports is paused for a moment. Please try again later, or call the barangay hall for anything urgent.')
      using errcode = 'check_violation';
  end if;
  if (select count(*) from public.reports r
       where r.resident_id = new.resident_id
         and r.created_at > now() - interval '24 hours') >= coalesce(v_limit, 20) then
    raise exception 'You have filed % reports in the last 24 hours, the most allowed. Please try again tomorrow, or visit the barangay hall.', coalesce(v_limit, 20)
      using errcode = 'check_violation';
  end if;
  return new;
end $$;


--
-- Name: enforce_media_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_media_cap() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  total integer;
begin
  select coalesce(sum(bytes), 0) into total
    from public.report_media where report_id = new.report_id;
  if total + new.bytes > 35 * 1024 * 1024 then
    raise exception 'Combined media for this report exceeds the 35 MB limit';
  end if;
  return new;
end $$;


--
-- Name: extensions_used(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extensions_used(p_report uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select count(*)::integer
    from public.sla_extensions e
    join public.reports r on r.id = e.report_id
   where e.report_id = p_report
     and e.created_at > coalesce(r.handed_up_at, '-infinity'::timestamptz)
$$;


--
-- Name: reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tracking_id text NOT NULL,
    resident_id uuid NOT NULL,
    is_anonymous boolean DEFAULT false NOT NULL,
    category public.complaint_category NOT NULL,
    subject text NOT NULL,
    description text NOT NULL,
    latitude double precision NOT NULL,
    longitude double precision NOT NULL,
    geom public.geography(Point,4326) GENERATED ALWAYS AS ((public.st_setsrid(public.st_makepoint(longitude, latitude), 4326))::public.geography) STORED,
    status public.report_status DEFAULT 'pending_review'::public.report_status NOT NULL,
    due_at timestamp with time zone,
    escalated_at timestamp with time zone,
    escalation_level smallint DEFAULT 0 NOT NULL,
    reopened_count smallint DEFAULT 0 NOT NULL,
    resolved_at timestamp with time zone,
    closed_at timestamp with time zone,
    deleted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    dispatch_attempts smallint DEFAULT 0 NOT NULL,
    awaiting_unit_since timestamp with time zone,
    appealed_at timestamp with time zone,
    client_ref uuid,
    location_label text,
    referred_to text,
    referral_note text,
    referred_at timestamp with time zone,
    referred_by uuid,
    overdue_notified_at timestamp with time zone,
    followed_up_at timestamp with time zone,
    follow_up_count integer DEFAULT 0 NOT NULL,
    resolution_submitted_at timestamp with time zone,
    resolution_returned_reason text,
    is_public boolean DEFAULT false NOT NULL,
    higher_official text,
    higher_official_note text,
    handed_up_at timestamp with time zone,
    handler_id uuid,
    handled_since timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT reports_description_check CHECK (((char_length(description) >= 10) AND (char_length(description) <= 2000))),
    CONSTRAINT reports_escalation_level_check CHECK (((escalation_level >= 0) AND (escalation_level <= 3))),
    CONSTRAINT reports_higher_official_check CHECK (((char_length(higher_official) >= 2) AND (char_length(higher_official) <= 80))),
    CONSTRAINT reports_higher_official_note_check CHECK ((char_length(higher_official_note) <= 300)),
    CONSTRAINT reports_latitude_check CHECK (((latitude >= ('-90'::integer)::double precision) AND (latitude <= (90)::double precision))),
    CONSTRAINT reports_location_label_check CHECK (((location_label IS NULL) OR ((char_length(location_label) >= 1) AND (char_length(location_label) <= 160)))),
    CONSTRAINT reports_longitude_check CHECK (((longitude >= ('-180'::integer)::double precision) AND (longitude <= (180)::double precision))),
    CONSTRAINT reports_reopened_count_check CHECK ((reopened_count >= 0)),
    CONSTRAINT reports_subject_check CHECK (((char_length(subject) >= 3) AND (char_length(subject) <= 150)))
);

ALTER TABLE ONLY public.reports REPLICA IDENTITY FULL;


--
-- Name: COLUMN reports.awaiting_unit_since; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.awaiting_unit_since IS 'Set when automatic dispatch found no available tanod. Cleared once a dispatch is created. Not a failure — the sweep keeps retrying while this is set.';


--
-- Name: COLUMN reports.appealed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.appealed_at IS 'Set once, by appeal_report() (0057), the first time a rejected complaint is reinstated on appeal. Never cleared or incremented — a marker, not a counter (see reopened_count for why appeals do not share it).';


--
-- Name: COLUMN reports.client_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.client_ref IS 'Client-generated id of the submission (resident app outbox). Unique per resident, so a resent report returns the one already filed instead of creating a duplicate. Null for reports filed without one.';


--
-- Name: COLUMN reports.location_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.location_label IS 'Nearest street/place from OpenStreetMap reverse geocoding (0068). Display only; latitude/longitude stay the record.';


--
-- Name: COLUMN reports.referred_to; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.referred_to IS 'The outside authority the admin referred this complaint to (0072), e.g. VAWC Desk. Set together with status closed.';


--
-- Name: COLUMN reports.higher_official; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.higher_official IS 'The barangay official the case was handed to after its extensions ran out (0079). The case stays open here, under that official.';


--
-- Name: file_report(public.complaint_category, text, text, double precision, double precision, boolean, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_report(p_category public.complaint_category, p_subject text, p_description text, p_latitude double precision, p_longitude double precision, p_is_anonymous boolean DEFAULT false, p_media jsonb DEFAULT '[]'::jsonb, p_client_ref uuid DEFAULT NULL::uuid) RETURNS public.reports
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports;
  v_item   jsonb;
begin
  if jsonb_typeof(coalesce(p_media, '[]'::jsonb)) <> 'array' then
    raise exception 'p_media must be a JSON array of {media_url, mime_type, bytes}'
      using errcode = 'invalid_parameter_value';
  end if;

  -- Already filed under this ref: hand back that report, file nothing.
  if p_client_ref is not null then
    select * into v_report
      from public.reports
     where resident_id = auth.uid()
       and client_ref = p_client_ref;
    if found then
      return v_report;
    end if;
  end if;

  begin
    insert into public.reports
      (resident_id, is_anonymous, category, subject, description,
       latitude, longitude, client_ref)
    values
      (auth.uid(), coalesce(p_is_anonymous, false), p_category,
       p_subject, p_description, p_latitude, p_longitude, p_client_ref)
    returning * into v_report;
  exception when unique_violation then
    -- Two sends of the same queued report raced; the other one won.
    select * into v_report
      from public.reports
     where resident_id = auth.uid()
       and client_ref = p_client_ref;
    return v_report;
  end;

  for v_item in select value from jsonb_array_elements(coalesce(p_media, '[]'::jsonb))
  loop
    insert into public.report_media (report_id, media_url, mime_type, bytes)
    values (v_report.id,
            v_item ->> 'media_url',
            v_item ->> 'mime_type',
            (v_item ->> 'bytes')::integer);
  end loop;

  return v_report;
end $$;


--
-- Name: FUNCTION file_report(p_category public.complaint_category, p_subject text, p_description text, p_latitude double precision, p_longitude double precision, p_is_anonymous boolean, p_media jsonb, p_client_ref uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.file_report(p_category public.complaint_category, p_subject text, p_description text, p_latitude double precision, p_longitude double precision, p_is_anonymous boolean, p_media jsonb, p_client_ref uuid) IS 'Submit Complaint Report, one transaction. SECURITY INVOKER: reports_resident_insert still decides whether this caller may file, and report_media_insert still decides whether these photos may attach. If any photo row is rejected the whole complaint rolls back, so a complaint is never stored with its evidence silently missing. p_client_ref (0066) makes a resend of the same submission return the report already filed.';


--
-- Name: finalize_retirement(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_retirement(p_request uuid, p_decision text, p_reason text DEFAULT NULL::text) RETURNS public.retirement_status
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_req    public.retirement_requests%rowtype;
  v_user   public.users%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_new    retirement_status;
  d        record;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may decide a retirement request';
  end if;

  if p_decision not in ('approve', 'deny') then
    raise exception 'Unknown decision: %', p_decision;
  end if;

  select * into v_req from public.retirement_requests where id = p_request for update;
  if not found then
    raise exception 'No such retirement request';
  end if;

  if v_req.status <> 'pending' then
    raise exception 'This request has already been decided (current status: %)',
      v_req.status;
  end if;

  if p_decision = 'deny' and v_reason is null then
    raise exception 'A reason is required when denying a retirement request';
  end if;

  select * into v_user from public.users where id = v_req.tanod_id for update;
  if not found then
    raise exception 'That tanod account no longer exists';
  end if;

  v_new := case p_decision when 'approve' then 'approved' else 'denied' end::retirement_status;

  update public.retirement_requests
     set status        = v_new,
         decided_at    = now(),
         decided_by    = auth.uid(),
         denial_reason = v_reason
   where id = p_request;

  if v_new = 'approved' then
    update public.users
       set is_retired  = true,
           retired_at  = now(),
           duty_status = null
     where id = v_user.id;

    -- Same protection set_account_suspension gives a suspended tanod
    -- (0013): a live dispatch cannot be left on a phone that is about
    -- to stop being checked.
    for d in
      update public.dispatches
         set state = 'expired'
       where tanod_id = v_user.id and state in ('assigned', 'accepted')
      returning report_id
    loop
      perform public.redispatch_report(d.report_id, 'assigned tanod has retired');
    end loop;
  end if;

  insert into public.notifications (user_id, kind, message)
  values (v_user.id, 'retirement',
          case v_new
            when 'approved' then
              'Your retirement has been approved. Thank you for your service — this account can no longer sign in.'
            else
              format('Your retirement request was not approved. Reason: %s', v_reason)
          end);

  return v_new;
end $$;


--
-- Name: FUNCTION finalize_retirement(p_request uuid, p_decision text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalize_retirement(p_request uuid, p_decision text, p_reason text) IS 'Manage Retirement Request, admin only. Approve sets is_retired/retired_at and releases any live dispatch, mirroring set_account_suspension exactly.';


--
-- Name: follow_up_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.follow_up_report(p_report uuid, p_message text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_msg    text := nullif(trim(coalesce(p_message, '')), '');
begin
  select * into v_report from public.reports
   where id = p_report and resident_id = auth.uid() and deleted_at is null
   for update;
  if not found then
    raise exception 'Complaint not found';
  end if;
  if v_report.status in ('resolved', 'closed', 'archived', 'rejected', 'cancelled') then
    raise exception 'This complaint is already finished';
  end if;
  if v_report.due_at is null or v_report.due_at > now() then
    raise exception 'You can follow up once the target date has passed';
  end if;
  if v_report.followed_up_at is not null
     and v_report.followed_up_at > now() - interval '24 hours' then
    raise exception 'You already followed up today. The barangay has been told.';
  end if;
  if v_msg is not null and char_length(v_msg) > 1000 then
    raise exception 'Keep the message under 1000 characters';
  end if;

  update public.reports
     set followed_up_at = now(), follow_up_count = follow_up_count + 1
   where id = p_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, v_report.status,
          'The resident followed up on this overdue complaint.');

  if v_msg is not null then
    insert into public.report_messages (report_id, author_id, from_barangay, body)
    values (p_report, auth.uid(), false, v_msg);
  end if;

  insert into public.notifications (user_id, report_id, kind, message)
  select u.id, p_report, 'sla_warning',
         'The resident followed up on overdue complaint ' || v_report.tracking_id
         || coalesce(': ' || left(v_msg, 140), '.')
    from public.users u where u.role = 'admin';
end $$;


--
-- Name: guard_last_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_last_admin() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_left integer;
begin
  if old.role = 'admin'
     and (new.role <> 'admin' or new.is_suspended) then
    select count(*) into v_left from public.users
     where role = 'admin' and not is_suspended and id <> old.id;
    if v_left = 0 then
      raise exception
        'This is the last active administrator. Appoint another before removing this one.';
    end if;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION guard_last_admin(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_last_admin() IS 'Refuses any update that would leave Barangay 183 with no active administrator.';


--
-- Name: guard_privileged_user_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_privileged_user_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- auth.uid() is null only for service_role / backend contexts, which
  -- bypass RLS anyway; an unauthenticated client never reaches this row.
  if auth.uid() is null or public.is_admin() then
    return new;
  end if;

  -- The resident's own account deletion (request_account_deletion) scrubs
  -- these fields on purpose.
  if current_setting('smartsumbong.account_deletion', true) = 'on' and new.id = auth.uid() then
    return new;
  end if;

  if new.role                   is distinct from old.role
     or new.verification_status is distinct from old.verification_status
     or new.is_suspended        is distinct from old.is_suspended
     or new.verified_by         is distinct from old.verified_by
     or new.verified_at         is distinct from old.verified_at
     or new.rejection_reason    is distinct from old.rejection_reason then
    raise exception
      'Only an administrator may change account role, verification, or suspension state';
  end if;

  if new.mobile_number is distinct from old.mobile_number then
    raise exception
      'Your mobile number is how you sign in. Please ask the barangay to change it.';
  end if;

  if new.full_name is distinct from old.full_name then
    raise exception
      'Please ask the barangay to change the name on your account.';
  end if;

  return new;
end $$;


--
-- Name: FUNCTION guard_privileged_user_fields(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_privileged_user_fields() IS 'Stops a resident editing fields that are not theirs to edit: role, verification and suspension (an admin''s), mobile_number (their login identity, derived in auth.users and only repairable with the service role) and full_name (what an admin compared against a government ID). Email remains theirs — it is contact-only since 0021.';


--
-- Name: hand_to_higher_official(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hand_to_higher_official(p_report uuid, p_official text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report   public.reports%rowtype;
  v_official text := nullif(trim(coalesce(p_official, '')), '');
  v_note     text := nullif(trim(coalesce(p_note, '')), '');
  v_cap      integer;
  v_used     integer;
  d          record;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may hand a case to a higher official';
  end if;
  if v_official is null or char_length(v_official) < 2 or char_length(v_official) > 80 then
    raise exception 'Name the official (2 to 80 characters)';
  end if;
  if v_note is not null and char_length(v_note) > 300 then
    raise exception 'The note can be at most 300 characters';
  end if;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if v_report.status in ('pending_review', 'resolved', 'closed', 'archived', 'rejected', 'cancelled')
     or v_report.referred_to is not null then
    raise exception 'Only an open complaint can be handed to a higher official';
  end if;

  select max_deadline_extensions into v_cap from public.operational_settings where id = 1;
  v_cap  := coalesce(v_cap, 2);
  v_used := public.extensions_used(p_report);
  if v_used < v_cap then
    raise exception 'The target date can still be extended (% of % used). Hand the case up once the extensions run out.', v_used, v_cap;
  end if;

  -- Whoever is on it is stood down and told.
  for d in select id, tanod_id from public.dispatches
            where report_id = p_report and state in ('assigned', 'accepted') loop
    update public.dispatches
       set state = 'rerouted', rerouted_at = now(),
           reroute_reason = 'Handed to ' || v_official
     where id = d.id;
    insert into public.notifications (user_id, report_id, kind, message)
    values (d.tanod_id, p_report, 'reroute',
            v_report.tracking_id || ' was handed to ' || v_official || '. You no longer need to act on it.');
  end loop;

  update public.reports
     set higher_official      = v_official,
         higher_official_note = v_note,
         handed_up_at         = now(),
         status = case when status in ('validated', 'assigned') then 'in_progress'::report_status else status end
   where id = p_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status,
          case when v_report.status in ('validated', 'assigned') then 'in_progress'::report_status else v_report.status end,
          format('Handed to %s after the target date was extended %s time(s).', v_official, v_used)
          || coalesce(' ' || v_note, ''));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          'Your complaint ' || v_report.tracking_id || ' is now handled by ' || v_official || '.'
          || coalesce(' ' || v_note, ''));
end $$;


--
-- Name: FUNCTION hand_to_higher_official(p_report uuid, p_official text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hand_to_higher_official(p_report uuid, p_official text, p_note text) IS 'Once a complaint''s extensions are used up (0079), the admin hands it to a barangay official: any tanod is stood down, the case stays open under that official, and a fresh extension allowance starts.';


--
-- Name: handle_new_auth_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_auth_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_full_name text := nullif(trim(new.raw_user_meta_data ->> 'full_name'), '');
  v_mobile    text := nullif(trim(new.raw_user_meta_data ->> 'mobile_number'), '');
  v_email     text := nullif(trim(new.raw_user_meta_data ->> 'contact_email'), '');
  v_role      text := coalesce(nullif(trim(new.raw_user_meta_data ->> 'role'), ''), 'resident');
  v_id_type   text := nullif(trim(new.raw_user_meta_data ->> 'id_type'), '');
  v_id_image  text := nullif(trim(new.raw_user_meta_data ->> 'id_image_url'), '');
  v_selfie    text := nullif(trim(new.raw_user_meta_data ->> 'selfie_url'), '');
  v_comma_pos int;
begin
  if current_setting('smartsumbong.provisioning_admin', true) = 'on' then
    return new;
  end if;

  if v_full_name is null then
    raise exception 'full_name is required at signup';
  end if;

  v_comma_pos := position(',' in v_full_name);
  if v_comma_pos <= 1
     or length(trim(substring(v_full_name from v_comma_pos + 1))) = 0 then
    raise exception 'full_name must be in the form Last Name, First Name';
  end if;

  if v_mobile is null then
    raise exception 'mobile_number is required at signup';
  end if;

  if v_mobile !~ '^\+639[0-9]{9}$' then
    raise exception 'mobile_number must be in the form +639XXXXXXXXX';
  end if;

  if new.email is distinct from public.auth_email_for(v_mobile) then
    raise exception 'auth identity does not match mobile_number';
  end if;

  if v_role not in ('resident', 'tanod') then
    raise exception 'role must be resident or tanod at signup';
  end if;

  if v_id_type is null then
    raise exception 'id_type is required at signup';
  end if;
  if not exists (select 1 from unnest(enum_range(null::id_document_type)) e
                  where e::text = v_id_type) then
    raise exception 'id_type % is not a recognised document type', v_id_type;
  end if;
  if v_id_image is null then
    raise exception 'id_image_url is required at signup';
  end if;
  if v_role = 'resident' and v_selfie is null then
    raise exception 'selfie_url is required at signup';
  end if;

  if v_email is not null and v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'contact_email is not a valid address';
  end if;

  insert into public.users (
    id, full_name, email, mobile_number, role,
    id_type, id_image_url, selfie_url,
    verification_status, verification_submitted_at
  )
  values (
    new.id, v_full_name, v_email, v_mobile, v_role::user_role,
    v_id_type::id_document_type, v_id_image, v_selfie,
    'pending', now()
  );

  return new;
end $_$;


--
-- Name: FUNCTION handle_new_auth_user(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handle_new_auth_user() IS 'Signup bridge. The auth address is synthetic and derived from mobile_number; contact_email is optional and arrives in metadata. Requires full_name (as "Last Name, First Name", 0032), mobile_number, id_type and id_image_url for every role; selfie_url is required for a resident but optional for a tanod (0036) — a tanod is matched to the barangay''s roster by an admin instead. Refuses any role other than resident or tanod. Runs in the same transaction as the auth.users insert, so a rejected application leaves no credential behind.';


--
-- Name: identity_media_in_use(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.identity_media_in_use(p_url text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.users
                  where id_image_url = p_url or selfie_url = p_url or avatar_url = p_url)
      or exists (select 1 from public.profile_requests
                  where id_image_url = p_url and status <> 'declined')
$$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(public.my_role() = 'admin', false)
$$;


--
-- Name: is_barangay_media_url(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_barangay_media_url(p_url text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'extensions'
    AS $_$
  select p_url ~
    '^https://res\.cloudinary\.com/nwb2kryl/image/upload/v[0-9]+/barangay/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|jpeg|png|webp)$'
$_$;


--
-- Name: FUNCTION is_barangay_media_url(p_url text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_barangay_media_url(p_url text) IS 'A delivery URL in the barangay''s Cloudinary cloud, folder barangay, UUIDv4 name, image extension. The pin for report_evidence (0079); mirrored by cloudinary_upload() in admin/includes/supabase.php.';


--
-- Name: is_evidence_media_url(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_evidence_media_url(p_url text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'extensions'
    AS $_$
  select public.is_media_url(p_url)
      or p_url ~
    '^https://res\.cloudinary\.com/nwb2kryl/video/upload/v[0-9]+/(reports|dispatch)/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(mp4|mov|webm|3gp)$'
$_$;


--
-- Name: FUNCTION is_evidence_media_url(p_url text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_evidence_media_url(p_url text) IS 'is_media_url() or a Cloudinary video URL in the reports/dispatch folders with a UUIDv4 name and a video extension. Used only by the report_media and dispatch_media pins (0060); identity columns stay on is_media_url(). Mirrored by _pinnedVideoUrl in mobile/core/lib/src/media_upload.dart — the two must change together.';


--
-- Name: is_identity_media_url(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_identity_media_url(p_url text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  select p_url ~ '^https://res\.cloudinary\.com/nwb2kryl/image/(upload|authenticated)/v[0-9]+/(ids|selfies|avatars)/'
$$;


--
-- Name: is_within_barangay(double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_within_barangay(p_lat double precision, p_lon double precision) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select st_covers(b.geom, st_setsrid(st_makepoint(p_lon, p_lat), 4326)::geography)
    from public.barangay_boundary b where b.id = 1
$$;


--
-- Name: location_is_fresh(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_is_fresh(p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select p_at is not null
     and p_at > now() - make_interval(mins => (
           select location_freshness_minutes from public.operational_settings where id = 1))
$$;


--
-- Name: log_duty_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_duty_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- Only an actual change, only for a tanod, never a null status.
  if new.role = 'tanod'
     and new.duty_status is not null
     and new.duty_status is distinct from old.duty_status then
    insert into public.attendance (tanod_id, duty_status)
    values (new.id, new.duty_status);
  end if;
  return new;
end $$;


--
-- Name: log_portal_error(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_portal_error(p_source text, p_page text, p_message text, p_detail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_page text := left(coalesce(nullif(trim(p_page), ''), '?'), 200);
  v_msg  text := left(coalesce(nullif(trim(p_message), ''), '(no message)'), 500);
  v_sig  text;
begin
  if p_source not in ('server', 'browser', 'function') then return; end if;
  -- 0119: only the Edge Functions themselves (service role) log as 'function'.
  if p_source = 'function' and coalesce(auth.role(), '') <> 'service_role' then return; end if;
  v_sig := md5(p_source || '|' || v_page || '|' || v_msg);
  insert into public.portal_errors (source, page, message, detail, signature)
  values (p_source, v_page, v_msg, left(p_detail, 2000), v_sig)
  on conflict (signature) do update
     set count = portal_errors.count + 1, last_seen = now(),
         detail = coalesce(excluded.detail, portal_errors.detail);
  -- Keep the table small: the 500 most recently seen.
  delete from public.portal_errors where id in (
    select id from public.portal_errors order by last_seen desc offset 500);
end $$;


--
-- Name: media_trash_done(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.media_trash_done(p_urls text[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Also drops entries that came back into use: nothing to delete there.
  delete from public.media_trash t
   where t.url = any (p_urls)
      or public.identity_media_in_use(t.url);
$$;


--
-- Name: media_trash_due(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.media_trash_due(p_limit integer DEFAULT 100) RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select t.url from public.media_trash t
   where t.queued_at < now() - interval '7 days'
     and not public.identity_media_in_use(t.url)
   order by t.queued_at
   limit p_limit
$$;


--
-- Name: my_admin_handover_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_admin_handover_status() RETURNS TABLE(admin_handover_until timestamp with time zone, admin_handover_role public.user_role, successor_name text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select u.admin_handover_until, u.admin_handover_role, s.full_name
    from public.users u
    left join public.users s on s.id = u.admin_handover_successor_id
   where u.id = auth.uid()
$$;


--
-- Name: my_resolution_authors(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_resolution_authors(p_report_ids uuid[]) RETURNS TABLE(report_id uuid, author_name text, is_system boolean, author_role text, resident_remark text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  select distinct on (sl.report_id)
         sl.report_id,
         coalesce(t.full_name, case when u.role = 'admin' then 'Barangay' else u.full_name end),
         sl.is_system,
         coalesce(t.role::text, u.role::text),
         public.resident_remark(sl.remark, sl.is_system)
    from public.status_logs sl
    join public.reports r on r.id = sl.report_id
    left join public.users u on u.id = sl.changed_by
    left join lateral (select * from public._resolution_tanod(sl.report_id, sl.remark, sl.new_status)) t on true
   where sl.new_status = 'resolved'
     and sl.report_id = any(p_report_ids)
     and r.resident_id = (select auth.uid())
   order by sl.report_id, sl.created_at desc
$$;


--
-- Name: my_retirement_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_retirement_status() RETURNS TABLE(status public.retirement_status, requested_at timestamp with time zone, decided_at timestamp with time zone, denial_reason text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select r.status, r.requested_at, r.decided_at, r.denial_reason
    from public.retirement_requests r
   where r.tanod_id = auth.uid()
   order by r.requested_at desc
   limit 1
$$;


--
-- Name: FUNCTION my_retirement_status(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_retirement_status() IS 'Latest retirement request for the calling tanod, or no rows if none was ever filed.';


--
-- Name: my_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_role() RETURNS public.user_role
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select role from public.users where id = auth.uid()
$$;


--
-- Name: my_status_log_authors(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_status_log_authors(p_report_id uuid) RETURNS TABLE(status_log_id uuid, author_name text, is_system boolean, author_role text, resident_remark text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  select sl.id,
         coalesce(t.full_name, case when u.role = 'admin' then 'Barangay' else u.full_name end),
         sl.is_system,
         coalesce(t.role::text, u.role::text),
         public.resident_remark(sl.remark, sl.is_system)
    from public.status_logs sl
    join public.reports r on r.id = sl.report_id
    left join public.users u on u.id = sl.changed_by
    left join lateral (select * from public._resolution_tanod(sl.report_id, sl.remark, sl.new_status)) t on true
   where sl.report_id = p_report_id
     and r.resident_id = (select auth.uid())
$$;


--
-- Name: nearest_available_tanod(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nearest_available_tanod(p_report uuid) RETURNS TABLE(tanod_id uuid, full_name text, metres double precision)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select u.id, u.full_name,
         st_distance(u.last_geom, r.geom) as metres
    from public.reports r
    cross join lateral (
      select u.* from public.users u
       where u.is_dispatchable
         and (select count(*) from public.dispatches d
               where d.tanod_id = u.id and d.state in ('assigned', 'accepted')) < public.tanod_dispatch_cap()
         and not exists (
           select 1 from public.dispatches d
            where d.tanod_id = u.id and d.report_id = p_report)
    ) u
   where r.id = p_report
   order by public.location_is_fresh(u.last_location_at) desc,
            st_distance(u.last_geom, r.geom) nulls last,
            u.last_location_at desc nulls last
$$;


--
-- Name: FUNCTION nearest_available_tanod(p_report uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.nearest_available_tanod(p_report uuid) IS 'Tanods who can take this report, best first: a fresh location, then the nearest last known one, then on-duty tanods with none yet (0067).';


--
-- Name: otp_attempt(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.otp_attempt(p_user uuid, p_purpose text, p_hash text, p_max integer DEFAULT 5) RETURNS TABLE(outcome text, attempts_left integer, otp_id uuid, new_mobile text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v public.password_otps%rowtype;
begin
  select * into v
    from public.password_otps o
   where o.user_id = p_user and o.purpose = p_purpose and o.used_at is null
   order by o.created_at desc
   limit 1
   for update;

  if not found or v.expires_at < now() or v.attempts >= p_max then
    return query select 'expired', 0, null::uuid, null::text;
    return;
  end if;

  if v.code_hash = p_hash then
    -- Marked used by the caller once the change it unlocks has gone through.
    return query select 'ok', p_max - v.attempts, v.id, v.new_mobile;
    return;
  end if;

  update public.password_otps set attempts = attempts + 1 where id = v.id;
  return query select 'wrong', greatest(0, p_max - v.attempts - 1), v.id, null::text;
end $$;


--
-- Name: FUNCTION otp_attempt(p_user uuid, p_purpose text, p_hash text, p_max integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.otp_attempt(p_user uuid, p_purpose text, p_hash text, p_max integer) IS '0114: checks one guess at the newest live SMS code, counting a wrong one under a row lock so parallel guesses cannot share a try. password-otp only.';


--
-- Name: ping_portal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ping_portal() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'net'
    AS $$
declare
  v_req   bigint;
  v_open  public.portal_outages;
  v_last2 boolean[];
begin
  -- File the answers that have arrived since the last run.
  update public.portal_uptime u
     set status = r.status_code,
         ok     = (r.status_code = 200 and not coalesce(r.timed_out, false)),
         error  = left(coalesce(r.error_msg, case when r.timed_out then 'timed out' end), 200)
    from net._http_response r
   where r.id = u.request_id and u.ok is null;
  update public.portal_uptime set ok = false, error = 'no answer'
   where ok is null and checked_at < now() - interval '15 minutes';
  delete from public.portal_uptime where checked_at < now() - interval '30 days';

  -- Two misses in a row open an outage (and alert); an answer closes it.
  select array_agg(ok order by checked_at desc) into v_last2
    from (select ok, checked_at from public.portal_uptime where ok is not null order by checked_at desc limit 2) x;
  select * into v_open from public.portal_outages where ended_at is null order by started_at desc limit 1;
  if v_open.id is null and v_last2 = array[false, false] then
    insert into public.portal_outages (started_at)
    select min(checked_at) from (select checked_at from public.portal_uptime where ok is not null order by checked_at desc limit 2) y;
    perform public._notify_admins('The admin portal stopped answering at '
      || to_char(now() at time zone 'Asia/Manila', 'HH12:MI AM') || '. It is checked every 10 minutes; you will be told when it is back.');
  elsif v_open.id is not null and coalesce(v_last2[1], false) then
    update public.portal_outages set ended_at = now() where id = v_open.id;
    perform public._notify_admins('The admin portal is answering again. It was down for about '
      || greatest(1, round(extract(epoch from now() - v_open.started_at) / 60))::int || ' minutes.');
  end if;

  select net.http_get('https://smartsumbong-ph.onrender.com/admin/ping.php', timeout_milliseconds := 60000) into v_req;
  insert into public.portal_uptime (request_id) values (v_req);
end $$;


--
-- Name: portal_uptime_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_uptime_summary() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_admin() then raise exception 'Only an administrator may see the uptime record'; end if;
  return json_build_object(
    'day_checks',  (select count(*) from portal_uptime where ok is not null and checked_at > now() - interval '1 day'),
    'day_ok',      (select count(*) from portal_uptime where ok and checked_at > now() - interval '1 day'),
    'week_checks', (select count(*) from portal_uptime where ok is not null and checked_at > now() - interval '7 days'),
    'week_ok',     (select count(*) from portal_uptime where ok and checked_at > now() - interval '7 days'),
    'last_at',     (select checked_at from portal_uptime where ok is not null order by checked_at desc limit 1),
    'last_ok',     (select ok from portal_uptime where ok is not null order by checked_at desc limit 1)
  );
end $$;


--
-- Name: post_dispatch_update(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_dispatch_update(p_dispatch uuid, p_body text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_d     public.dispatches%rowtype;
  v_admin boolean := public.is_admin();
  v_body  text := nullif(trim(coalesce(p_body, '')), '');
  v_id    uuid;
  v_tick  text;
  m       jsonb;
begin
  select * into v_d from public.dispatches where id = p_dispatch;
  if not found then
    raise exception 'Dispatch not found';
  end if;

  if v_admin then
    if v_d.state not in ('assigned', 'accepted') then
      raise exception 'This dispatch is closed';
    end if;
  elsif v_d.tanod_id is distinct from auth.uid() or v_d.state <> 'accepted' then
    raise exception 'Dispatch not found, not yours, or not accepted';
  end if;

  if v_body is null and jsonb_array_length(coalesce(p_media, '[]'::jsonb)) = 0 then
    raise exception 'An update needs a message or a photo';
  end if;
  if jsonb_array_length(coalesce(p_media, '[]'::jsonb)) > 6 then
    raise exception 'Up to 6 attachments per update';
  end if;

  insert into public.dispatch_updates (dispatch_id, author_id, kind, body)
  values (p_dispatch, auth.uid(), 'note', v_body)
  returning id into v_id;

  for m in select * from jsonb_array_elements(coalesce(p_media, '[]'::jsonb)) loop
    insert into public.dispatch_media (dispatch_id, update_id, media_url, mime_type, bytes)
    values (p_dispatch, v_id, m->>'media_url', m->>'mime_type', (m->>'bytes')::integer);
  end loop;

  if v_admin and v_d.tanod_id is not null then
    select tracking_id into v_tick from public.reports where id = v_d.report_id;
    insert into public.notifications (user_id, report_id, kind, message)
    values (v_d.tanod_id, v_d.report_id, 'status_change'::notification_kind,
            'Barangay on ' || coalesce(v_tick, 'your dispatch') || ': '
            || coalesce(left(v_body, 140), 'sent a photo'));
  end if;

  return v_id;
end $$;


--
-- Name: post_report_message(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_report_message(p_report uuid, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_admin  boolean := public.is_admin();
  v_body   text := nullif(trim(coalesce(p_body, '')), '');
  v_id     uuid;
begin
  if v_body is null then
    raise exception 'Write a message first';
  end if;
  if char_length(v_body) > 1000 then
    raise exception 'Keep the message under 1000 characters';
  end if;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null;
  if not found or (not v_admin and v_report.resident_id is distinct from auth.uid()) then
    raise exception 'Complaint not found';
  end if;

  insert into public.report_messages (report_id, author_id, from_barangay, body)
  values (p_report, auth.uid(), v_admin, v_body)
  returning id into v_id;

  if v_admin then
    insert into public.notifications (user_id, report_id, kind, message)
    values (v_report.resident_id, p_report, 'status_change',
            'The barangay replied about ' || v_report.tracking_id || ': ' || left(v_body, 140));
  else
    insert into public.notifications (user_id, report_id, kind, message)
    select u.id, p_report, 'status_change',
           'A resident asked about ' || v_report.tracking_id || ': ' || left(v_body, 140)
      from public.users u where u.role = 'admin';
  end if;

  return v_id;
end $$;


--
-- Name: profile_requests_queue_media_trash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profile_requests_queue_media_trash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.queue_media_trash(old.id_image_url);
    return old;
  end if;
  if new.status = 'declined' and old.status <> 'declined' then
    perform public.queue_media_trash(new.id_image_url);
  end if;
  return new;
end $$;


--
-- Name: promote_to_admin(uuid, text, integer, public.user_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promote_to_admin(p_user uuid, p_reason text DEFAULT NULL::text, p_handover_days integer DEFAULT NULL::integer, p_revert_role public.user_role DEFAULT NULL::public.user_role) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user   public.users%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may appoint another administrator';
  end if;

  select * into v_user from public.users where id = p_user for update;
  if not found then
    raise exception 'No such account';
  end if;

  if v_user.role = 'admin' then
    raise exception '% is already an administrator', public.display_name(v_user.full_name);
  end if;

  if v_user.verification_status <> 'verified' then
    raise exception
      '% is not a verified account. Only a verified resident or tanod of Barangay 183 may be appointed.',
      public.display_name(v_user.full_name);
  end if;

  if v_user.is_suspended then
    raise exception '% is suspended and cannot be appointed', public.display_name(v_user.full_name);
  end if;

  if p_handover_days is not null then
    if p_handover_days < 1 or p_handover_days > 90 then
      raise exception 'A handover window must be between 1 and 90 days';
    end if;
    if p_revert_role is null or p_revert_role = 'admin' then
      raise exception 'Choose the role you will return to when the handover ends';
    end if;
  end if;

  -- A tanod who becomes an admin stops being dispatchable: they are no
  -- longer on the roster, and leaving them in it would send incidents to
  -- someone sitting at a desk. sync_dispatchable does this on its own
  -- once the role changes, but the duty status is cleared here so the
  -- Personnel screen does not still show them as On Duty.
  update public.users
     set role        = 'admin',
         duty_status = null
   where id = p_user;

  if p_handover_days is not null then
    update public.users
       set admin_handover_until        = now() + (p_handover_days || ' days')::interval,
           admin_handover_role         = p_revert_role,
           admin_handover_successor_id = p_user
     where id = auth.uid();
  end if;

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (p_user, auth.uid(), 'promoted_to_admin',
          coalesce(v_reason, format('Appointed by %s',
            (select public.display_name(full_name) from public.users where id = auth.uid()))));

  if p_handover_days is not null then
    insert into public.account_audit (subject_id, actor_id, action, detail)
    values (auth.uid(), auth.uid(), 'handover_scheduled',
            format('Training %s for up to %s day(s); returns to %s on %s',
              public.display_name(v_user.full_name), p_handover_days, p_revert_role,
              to_char(now() + (p_handover_days || ' days')::interval, 'Mon dd, yyyy')));
  end if;

  insert into public.notifications (user_id, kind, message)
  values (p_user, 'verification',
          'You have been given barangay administrator access to Smart Sumbong.'
          || case when p_handover_days is not null
               then format(' The outgoing administrator will continue to help for up to %s day(s).', p_handover_days)
               else '' end);

  return public.display_name(v_user.full_name);
end $$;


--
-- Name: FUNCTION promote_to_admin(p_user uuid, p_reason text, p_handover_days integer, p_revert_role public.user_role); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.promote_to_admin(p_user uuid, p_reason text, p_handover_days integer, p_revert_role public.user_role) IS 'Grants admin access. p_handover_days/p_revert_role (0055) are both optional -- when given, also schedules the CALLING admin''s own return to p_revert_role once p_handover_days elapse (max 90).';


--
-- Name: public_incidents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_incidents() RETURNS TABLE(id uuid, category public.complaint_category, status public.report_status, latitude double precision, longitude double precision, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  select r.id, r.category, r.status, r.latitude, r.longitude, r.created_at
    from public.reports r
   where r.is_public
     and r.deleted_at is null
     and r.status not in ('rejected', 'cancelled')
     and auth.uid() is not null
   order by r.created_at desc
   limit 500
$$;


--
-- Name: purge_old_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_old_notifications() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  delete from public.notifications
   where (is_read and created_at < now() - interval '90 days')
      or created_at < now() - interval '365 days';
$$;


--
-- Name: FUNCTION purge_old_notifications(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_old_notifications() IS '0115: daily. Read notifications go after 90 days, any after a year.';


--
-- Name: queue_media_trash(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_media_trash(p_url text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.media_trash (url)
  select p_url
   where p_url is not null and public.is_identity_media_url(p_url)
  on conflict (url) do update set queued_at = now();
$$;


--
-- Name: redispatch_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redispatch_report(p_report uuid, p_why text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_attempts smallint;
  v_max      smallint;
  v_next     uuid;
begin
  select max_dispatch_attempts into v_max from public.operational_settings where id = 1;

  update public.reports
     set dispatch_attempts = dispatch_attempts + 1,
         status = 'validated'
   where id = p_report
  returning dispatch_attempts into v_attempts;

  if v_attempts > v_max then
    update public.reports
       set escalation_level = greatest(escalation_level, 1),
           escalated_at = coalesce(escalated_at, now())
     where id = p_report;

    insert into public.status_logs (report_id, changed_by, old_status, new_status,
                                    remark, is_system)
    select p_report, r.resident_id, 'validated', 'validated',
           format('Automatic dispatch gave up after %s offers (%s) — manual assignment required',
                  v_attempts, p_why), true
      from public.reports r where r.id = p_report;

    insert into public.notifications (user_id, report_id, kind, message)
    select id, p_report, 'escalation',
           'A report could not be dispatched automatically and needs manual assignment.'
      from public.users where role = 'admin';
    return null;
  end if;

  insert into public.status_logs (report_id, changed_by, old_status, new_status,
                                  remark, is_system)
  select p_report, r.resident_id, 'assigned', 'validated',
         format('Re-dispatching: %s (offer %s of %s)', p_why, v_attempts, v_max), true
    from public.reports r where r.id = p_report;

  select public.auto_dispatch(p_report) into v_next;
  return v_next;
end $$;


--
-- Name: refer_report(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refer_report(p_report uuid, p_agency text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_agency text := nullif(trim(coalesce(p_agency, '')), '');
  v_note   text := nullif(trim(coalesce(p_note, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may escalate a complaint';
  end if;
  if v_agency is null then
    raise exception 'Choose the office the complaint is escalated to';
  end if;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if v_report.referred_to is not null then
    raise exception 'This complaint was already escalated to %', v_report.referred_to;
  end if;
  if v_report.status in ('closed', 'archived', 'rejected', 'cancelled') then
    raise exception 'This complaint is already closed';
  end if;

  update public.dispatches
     set state = 'rerouted', rerouted_at = now(),
         reroute_reason = 'Escalated to ' || v_agency
   where report_id = p_report and state in ('assigned', 'accepted');

  update public.reports
     set status        = 'closed',
         closed_at     = now(),
         referred_to   = v_agency,
         referral_note = v_note,
         referred_at   = now(),
         referred_by   = auth.uid()
   where id = p_report;

  -- Any request still waiting on this complaint is settled by this.
  update public.escalation_requests
     set status = 'approved', decided_by = auth.uid(), decided_at = now(),
         decided_office = v_agency
   where report_id = p_report and status = 'pending';

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, 'closed',
          'Escalated to ' || v_agency || coalesce(': ' || v_note, '.'));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          format('Your complaint %s has been escalated to the %s, which handles this kind of case.%s',
                 v_report.tracking_id, v_agency,
                 coalesce(' Note from the barangay: ' || v_note, '')));
end $$;


--
-- Name: refuse_audit_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refuse_audit_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if tg_op = 'UPDATE' then
    raise exception 'The audit trail cannot be edited. Add a correcting entry instead.';
  end if;

  -- Branch on the table before touching a column, because PL/pgSQL
  -- evaluates the whole condition and account_audit has no report_id.
  if tg_table_name = 'account_audit' then
    raise exception 'Account audit entries cannot be deleted.';
  end if;

  -- A DELETE on a complaint trail is only legitimate as a cascade from a
  -- report that has already gone. If the parent is still there, someone
  -- is removing a single entry — exactly what this guards against.
  if exists (select 1 from public.reports where id = old.report_id) then
    raise exception 'Audit entries cannot be deleted while the complaint exists.';
  end if;

  return old;
end $$;


--
-- Name: register_device_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_device_token(p_token text, p_platform text DEFAULT 'android'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;
  if p_token is null or char_length(trim(p_token)) = 0 then
    raise exception 'A device token is required';
  end if;

  insert into public.device_tokens (user_id, fcm_token, platform)
  values (auth.uid(), trim(p_token), coalesce(nullif(trim(p_platform), ''), 'android'))
  on conflict (user_id, fcm_token)
  do update set updated_at = now(), platform = excluded.platform;
end $$;


--
-- Name: register_login_failure(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_login_failure(p_mobile text) RETURNS TABLE(locked boolean, seconds_remaining integer, attempts_remaining integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_now    timestamptz := now();
  v_source text := public.request_source();
  v_hits   integer;
  v_count  integer;
  v_locked timestamptz;
begin
  if p_mobile is null or p_mobile !~ '^\+63[0-9]{10}$' then
    return query select false, 0, 5;
    return;
  end if;

  if v_source is not null then
    insert into public.login_failure_sources as s (source, window_start, hits)
    values (v_source, v_now, 1)
    on conflict (source) do update
       set hits = case when s.window_start < v_now - interval '15 minutes' then 1 else s.hits + 1 end,
           window_start = case when s.window_start < v_now - interval '15 minutes' then v_now else s.window_start end
    returning hits into v_hits;

    if v_hits > 20 then
      return query select false, 0, 5;
      return;
    end if;

    -- Keep the table to the addresses seen today.
    if v_hits = 1 then
      delete from public.login_failure_sources where window_start < v_now - interval '1 day';
    end if;
  end if;

  -- Unchanged from 0031 from here on.
  insert into public.login_attempts (mobile_number, failed_count, locked_until, last_attempt_at)
  values (p_mobile, 1, null, v_now)
  on conflict (mobile_number) do update
     set failed_count = case
           when login_attempts.locked_until is not null
                and login_attempts.locked_until <= v_now
           then 1
           else login_attempts.failed_count + 1
         end,
         locked_until = case
           when (case
                   when login_attempts.locked_until is not null
                        and login_attempts.locked_until <= v_now
                   then 1
                   else login_attempts.failed_count + 1
                 end) >= 5
           then v_now + interval '30 minutes'
           else null
         end,
         last_attempt_at = v_now
  returning failed_count, locked_until
    into v_count, v_locked;

  if v_count >= 5 then
    return query select true,
      greatest(0, ceil(extract(epoch from (v_locked - v_now)))::int),
      0;
  else
    return query select false, 0, greatest(0, 5 - v_count);
  end if;
end $_$;


--
-- Name: FUNCTION register_login_failure(p_mobile text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.register_login_failure(p_mobile text) IS 'Call after GoTrue rejects a password for this number — never for not-confirmed, suspended, or rate-limited responses, which are not a guessed password. Returns whether this attempt just triggered the 30-minute lock, and how many attempts remain if not.';


--
-- Name: reject_resolution(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_resolution(p_report uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_d      public.dispatches%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may return a resolution';
  end if;
  if v_reason is null then
    raise exception 'Say what the tanod still needs to do';
  end if;
  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found or v_report.resolution_submitted_at is null then
    raise exception 'There is no resolution waiting for approval';
  end if;

  select * into v_d from public.dispatches
   where report_id = p_report and state = 'resolved'
   order by resolved_at desc nulls last limit 1;

  -- Back to the tanod: their dispatch is open again.
  if v_d.id is not null then
    update public.dispatches set state = 'accepted', resolved_at = null where id = v_d.id;
    insert into public.dispatch_updates (dispatch_id, author_id, kind, body)
    values (v_d.id, auth.uid(), 'note', 'Resolution returned: ' || v_reason);
    insert into public.notifications (user_id, report_id, kind, message)
    values (v_d.tanod_id, p_report, 'status_change',
            'The barangay returned your resolution of ' || v_report.tracking_id || ': ' || left(v_reason, 140));
  end if;

  update public.reports
     set status = 'in_progress', resolution_submitted_at = null,
         resolution_returned_reason = v_reason
   where id = p_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, 'in_progress',
          'Resolution returned to the tanod: ' || v_reason);
end $$;


--
-- Name: release_case(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_case(p_report uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_h uuid;
begin
  if not public.is_admin() then raise exception 'Only an administrator may release a case'; end if;
  select handler_id into v_h from public.reports where id = p_report and deleted_at is null for update;
  if not found then raise exception 'No such report'; end if;
  if v_h is distinct from auth.uid() then raise exception 'Only the handler can release this case'; end if;
  perform set_config('smartsumbong.handler_change', 'on', true);
  update public.reports set handler_id = null, handled_since = null where id = p_report;
  perform set_config('smartsumbong.handler_change', 'off', true);
  insert into public.case_handler_log (report_id, admin_id, action) values (p_report, auth.uid(), 'release');
end $$;


--
-- Name: reopen_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_report(p_report uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_old report_status;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may reopen a complaint';
  end if;

  select status into v_old from public.reports where id = p_report;

  -- 0071: the old 24-hour window is gone; the admin sets a new date
  -- when assigning again.
  update public.reports
     set status = 'validated',
         reopened_count = reopened_count + 1,
         resolved_at = null,
         due_at = null
   where id = p_report and status in ('resolved', 'closed');

  if not found then
    raise exception 'Report is not in a reopenable state';
  end if;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_old, 'validated', 'Reopened: ' || p_reason);
end $$;


--
-- Name: report_hotspots(timestamp with time zone, timestamp with time zone, public.complaint_category); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_hotspots(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category DEFAULT NULL::public.complaint_category) RETURNS TABLE(cluster_id integer, centroid_lat double precision, centroid_lng double precision, report_count integer, top_category public.complaint_category, first_at timestamp with time zone, last_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  with scoped as (
    select r.category, r.created_at,
           st_transform(r.geom::geometry, 3857) as g3857
      from public.reports r
     where r.deleted_at is null
       and r.created_at >= p_from
       and r.created_at <  p_to
       and (p_category is null or r.category = p_category)
  ),
  clustered as (
    select *,
           st_clusterdbscan(g3857, eps := 45, minpoints := 3) over () as cid
      from scoped
  )
  select
    cid,
    st_y(st_transform(st_centroid(st_collect(g3857)), 4326)),
    st_x(st_transform(st_centroid(st_collect(g3857)), 4326)),
    count(*)::integer,
    mode() within group (order by category),
    min(created_at),
    max(created_at)
    from clustered
   where cid is not null   -- DBSCAN "noise": no cluster, not a hotspot
   group by cid
   order by count(*) desc
$$;


--
-- Name: FUNCTION report_hotspots(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.report_hotspots(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category) IS 'Real spatial clustering (PostGIS ST_ClusterDBSCAN, 45m/3pts) over reports in a window, ranked by size. RLS-scoped like dashboard_metrics -- an admin sees barangay-wide hotspots, anyone else only ever clusters what reports_resident_read already lets them see.';


--
-- Name: request_account_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_account_deletion() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_uid         uuid := auth.uid();
  v_role        user_role;
  v_has_reports boolean;
  v_scrub_email text;
  v_scrub_phone text;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;
  -- 0089: the scrub below changes the name and number, which
  -- guard_privileged_user_fields refuses a resident; this call is allowed.
  perform set_config('smartsumbong.account_deletion', 'on', true);

  select role into v_role from public.users where id = v_uid;
  if v_role is null then
    raise exception 'No such account';
  end if;
  if v_role <> 'resident' then
    raise exception 'Self-service account deletion is currently only available to resident accounts';
  end if;

  -- 0090: an account-change audit entry (every verified account has one)
  -- pins the row just like a filed complaint does, so it is kept and
  -- scrubbed too; a hard delete would be refused by account_audit.
  select exists(select 1 from public.reports where resident_id = v_uid)
      or exists(select 1 from public.account_audit where subject_id = v_uid or actor_id = v_uid)
    into v_has_reports;

  if not v_has_reports then
    -- Nothing else in this schema references this account. The caller
    -- hard-deletes auth.users, which cascades everywhere on its own.
    return true;
  end if;

  -- Unique placeholders, not a shared literal â€” public.users.email and
  -- .mobile_number are both `unique`, and a second resident deleting
  -- their account the same day must not collide with the first.
  v_scrub_email := 'deleted+' || replace(v_uid::text, '-', '') || '@smartsumbong.invalid';
  v_scrub_phone := 'deleted-' || left(replace(v_uid::text, '-', ''), 10);

  update public.users
     set full_name        = 'Deleted Resident',
         email             = v_scrub_email,
         mobile_number     = v_scrub_phone,
         id_image_url      = null,
         selfie_url        = null,
         address           = null,
         avatar_url        = null,
         rejection_reason  = null,
         is_suspended      = true,
         suspended_reason  = 'Account deleted by the resident. Their filed reports remain on record.'
   where id = v_uid;

  delete from public.device_tokens where user_id = v_uid;

  return false;
end $$;


--
-- Name: FUNCTION request_account_deletion(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_account_deletion() IS 'Self-service account deletion, resident-only, called by the delete-account Edge Function as the resident''s own session. Returns true when it is safe for the caller to hard-delete auth.users (no reports on file), false when it has instead scrubbed public.users in place and the caller should ban the auth user -- reports are never destroyed, same philosophy as reports.deleted_at.';


--
-- Name: request_additional_details(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_additional_details(p_report uuid, p_message text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_status  report_status;
  v_owner   uuid;
  v_ticket  text;
  v_message text := nullif(trim(p_message), '');
  v_id      uuid;
begin
  if v_message is null then
    raise exception 'Please say what details you need';
  end if;
  if char_length(v_message) > 300 then
    raise exception 'Keep the request under 300 characters';
  end if;

  select status, resident_id, tracking_id
    into v_status, v_owner, v_ticket
    from public.reports
   where id = p_report and deleted_at is null;

  if v_status is null then
    raise exception 'Report not found';
  end if;

  if not (public.is_admin()
          or exists (select 1 from public.dispatches d
                      where d.report_id = p_report
                        and d.tanod_id = auth.uid()
                        and d.state = 'accepted')) then
    raise exception 'Only the tanod handling this report can ask for more details';
  end if;

  if v_status not in ('assigned', 'in_progress', 'offline_investigation') then
    raise exception 'More details can only be asked for while the report is being worked on';
  end if;

  if exists (select 1 from public.detail_requests
              where report_id = p_report and responded_at is null) then
    raise exception 'There is already a request for more details waiting on the resident';
  end if;

  insert into public.detail_requests (report_id, requested_by, message)
  values (p_report, auth.uid(), v_message)
  returning id into v_id;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark)
  values
    (p_report, auth.uid(), v_status, v_status,
     'More details requested: ' || v_message);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_owner, p_report, 'status_change'::notification_kind,
          'More details needed for ' || v_ticket || ': ' || v_message);

  return v_id;
end $$;


--
-- Name: FUNCTION request_additional_details(p_report uuid, p_message text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_additional_details(p_report uuid, p_message text) IS 'The accepted tanod (or an admin) asks the resident for more details on a report being worked on. One open request per report. Logs to status_logs and notifies the resident. 0065.';


--
-- Name: request_appeal(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_appeal(p_report uuid, p_reason text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_status report_status;
  v_owner  uuid;
  v_ticket text;
  v_item   jsonb;
begin
  if nullif(trim(p_reason), '') is null then
    raise exception 'Please explain why this rejection should be reviewed again';
  end if;

  if jsonb_typeof(coalesce(p_media, '[]'::jsonb)) <> 'array' then
    raise exception 'p_media must be a JSON array of {media_url, mime_type, bytes}'
      using errcode = 'invalid_parameter_value';
  end if;

  select status, resident_id, tracking_id
    into v_status, v_owner, v_ticket
    from public.reports
   where id = p_report and deleted_at is null;

  if v_status is null then
    raise exception 'Report not found';
  end if;
  if v_owner is distinct from auth.uid() then
    raise exception 'Only the resident who filed a report may appeal it';
  end if;
  if v_status <> 'rejected' then
    raise exception 'Only a rejected complaint can be appealed';
  end if;

  -- The request is a notification, not a status change. An admin acts on
  -- it with appeal_report(), which is where due_at and appealed_at live
  -- — the same split request_reopen()/reopen_report() already use.
  insert into public.notifications (user_id, kind, message)
  select a.id, 'status_change',
         'Appeal requested for ' || v_ticket || ': ' || trim(p_reason)
    from public.users a
   where a.role = 'admin'
     and not a.is_suspended;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark)
  values
    (p_report, auth.uid(), v_status, v_status,
     'Resident appealed the rejection: ' || trim(p_reason));

  -- Same insert idiom as request_reopen() (0037) — report_media_insert
  -- and report_media_url_pinned still apply; SECURITY DEFINER bypasses
  -- RLS the same way the rest of this function already does, so the
  -- ownership check above is what makes this safe, not the policy.
  for v_item in select value from jsonb_array_elements(coalesce(p_media, '[]'::jsonb))
  loop
    insert into public.report_media (report_id, media_url, mime_type, bytes)
    values (p_report,
            v_item ->> 'media_url',
            v_item ->> 'mime_type',
            (v_item ->> 'bytes')::integer);
  end loop;
end $$;


--
-- Name: FUNCTION request_appeal(p_report uuid, p_reason text, p_media jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_appeal(p_report uuid, p_reason text, p_media jsonb) IS 'The resident disputes a denial; the barangay decides. Notifies admins, writes the request to status_logs, and optionally attaches evidence to report_media, without changing the report''s status. SECURITY DEFINER for the same reason as request_reopen.';


--
-- Name: request_escalation(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_escalation(p_dispatch uuid, p_reason text, p_office text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_d      public.dispatches%rowtype;
  v_tick   text;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_id     uuid;
begin
  select * into v_d from public.dispatches
   where id = p_dispatch and tanod_id = auth.uid() and state = 'accepted';
  if not found then
    raise exception 'Dispatch not found, not yours, or not accepted';
  end if;
  if v_reason is null then
    raise exception 'Say why this needs to go beyond the barangay';
  end if;
  if exists (select 1 from public.escalation_requests
              where report_id = v_d.report_id and status = 'pending') then
    raise exception 'An escalation request for this complaint is already waiting';
  end if;

  insert into public.escalation_requests (report_id, dispatch_id, requested_by, reason, suggested_office)
  values (v_d.report_id, p_dispatch, auth.uid(), v_reason, nullif(trim(coalesce(p_office, '')), ''))
  returning id into v_id;

  select tracking_id into v_tick from public.reports where id = v_d.report_id;

  insert into public.dispatch_updates (dispatch_id, author_id, kind, body)
  values (p_dispatch, auth.uid(), 'note', 'Escalation requested: ' || v_reason);

  insert into public.notifications (user_id, report_id, kind, message)
  select u.id, v_d.report_id, 'escalation',
         'Escalation requested for ' || v_tick || ': ' || left(v_reason, 140)
    from public.users u where u.role = 'admin';

  return v_id;
end $$;


--
-- Name: request_id_reupload(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_id_reupload(p_id_type text, p_id_image_url text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_name text;
begin
  select full_name into v_name from public.users where id = auth.uid() and role in ('resident', 'tanod');
  if v_name is null then
    raise exception 'Only a resident or tanod account can send an ID';
  end if;
  if not exists (select 1 from unnest(enum_range(null::id_document_type)) e where e::text = p_id_type) then
    raise exception 'Choose the type of ID';
  end if;
  if p_id_image_url is null or not public.is_media_url(p_id_image_url) or p_id_image_url !~ '/ids/' then
    raise exception 'The ID photo did not upload correctly. Try again.';
  end if;
  if exists (select 1 from public.profile_requests where user_id = auth.uid() and kind = 'id_document' and status = 'pending') then
    raise exception 'You already have an ID waiting for the barangay';
  end if;

  insert into public.profile_requests (user_id, kind, id_type, id_image_url, reason)
  values (auth.uid(), 'id_document', p_id_type::id_document_type, p_id_image_url, nullif(trim(coalesce(p_reason, '')), ''));
  perform public._notify_admins(public.display_name(v_name) || ' sent a new photo of their ID.', auth.uid());
end $$;


--
-- Name: request_ocr_rescan(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_ocr_rescan(p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user public.users%rowtype;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may request an ID re-check';
  end if;

  select * into v_user from public.users where id = p_user for update;
  if not found then
    raise exception 'No such account';
  end if;

  if v_user.id_image_url is null then
    raise exception 'This account has no ID photo on file to re-check';
  end if;

  update public.users
     set ocr_rescan_requested_at = now()
   where id = p_user;

  insert into public.notifications (user_id, kind, message)
  values (p_user, 'status_change',
    'The barangay asked to re-check your uploaded ID. Open the app to complete it.');
end $$;


--
-- Name: FUNCTION request_ocr_rescan(p_user uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_ocr_rescan(p_user uuid) IS 'Admin-only. Flags an account for the resident''s own app to silently re-run on-device OCR against its already-uploaded ID photo next time it opens. Does not run OCR itself -- there is no server-side OCR in this project, see 0039''s header.';


--
-- Name: request_profile_change(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_profile_change(p_field text, p_value text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_name   text;
  v_value  text := trim(coalesce(p_value, ''));
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_comma  int;
begin
  select full_name into v_name from public.users where id = auth.uid();
  if v_name is null then
    raise exception 'Not signed in';
  end if;
  if p_field not in ('mobile_number', 'full_name') then
    raise exception 'Only a name or mobile number change can be requested';
  end if;

  if p_field = 'mobile_number' then
    if v_value !~ '^\+639[0-9]{9}$' then
      raise exception 'Enter the mobile number as 09XXXXXXXXX';
    end if;
    perform public._notify_admins(public.display_name(v_name) || ' asked to change their mobile number to ' || v_value
                                  || coalesce(' — ' || v_reason, '') || '. Changing a number is done at the counter.', auth.uid());
    return;
  end if;

  v_comma := position(',' in v_value);
  if v_comma <= 1 or length(trim(substring(v_value from v_comma + 1))) = 0 then
    raise exception 'Enter both a first name and a last name';
  end if;
  if exists (select 1 from public.profile_requests where user_id = auth.uid() and kind = 'full_name' and status = 'pending') then
    raise exception 'You already have a name change waiting for the barangay';
  end if;

  insert into public.profile_requests (user_id, kind, new_full_name, reason)
  values (auth.uid(), 'full_name', v_value, v_reason);
  perform public._notify_admins(public.display_name(v_name) || ' asked to change their name to ' || public.display_name(v_value)
                                || coalesce(' — ' || v_reason, '') || '.', auth.uid());
end $_$;


--
-- Name: FUNCTION request_profile_change(p_field text, p_value text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_profile_change(p_field text, p_value text, p_reason text) IS 'Notifies admins that a resident wants their number or name changed. Changes nothing: both fields require a person to check an ID, and mobile_number additionally requires a service-role update to auth.users that no client should be able to make.';


--
-- Name: request_reopen(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_reopen(p_report uuid, p_reason text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_status  report_status;
  v_owner   uuid;
  v_ticket  text;
  v_item    jsonb;
begin
  if nullif(trim(p_reason), '') is null then
    raise exception 'Please say why this report should be reopened';
  end if;

  if jsonb_typeof(coalesce(p_media, '[]'::jsonb)) <> 'array' then
    raise exception 'p_media must be a JSON array of {media_url, mime_type, bytes}'
      using errcode = 'invalid_parameter_value';
  end if;

  select status, resident_id, tracking_id
    into v_status, v_owner, v_ticket
    from public.reports
   where id = p_report and deleted_at is null;

  if v_status is null then
    raise exception 'Report not found';
  end if;
  if v_owner is distinct from auth.uid() then
    raise exception 'Only the resident who filed a report may ask to reopen it';
  end if;
  if v_status not in ('resolved', 'closed') then
    raise exception 'Only a finished report can be reopened';
  end if;

  -- The request is a notification, not a status change. An admin acts on
  -- it with reopen_report(), which is where the SLA clock and the
  -- reopened_count live.
  insert into public.notifications (user_id, kind, message)
  select a.id, 'status_change',
         'Reopen requested for ' || v_ticket || ': ' || trim(p_reason)
    from public.users a
   where a.role = 'admin'
     and not a.is_suspended;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark)
  values
    (p_report, auth.uid(), v_status, v_status,
     'Resident requested reopening: ' || trim(p_reason));

  -- Same insert idiom as file_report() (0017) — report_media_insert
  -- and report_media_url_pinned still apply; SECURITY DEFINER bypasses
  -- RLS the same way the rest of this function already does, so the
  -- ownership check above is what makes this safe, not the policy.
  for v_item in select value from jsonb_array_elements(coalesce(p_media, '[]'::jsonb))
  loop
    insert into public.report_media (report_id, media_url, mime_type, bytes)
    values (p_report,
            v_item ->> 'media_url',
            v_item ->> 'mime_type',
            (v_item ->> 'bytes')::integer);
  end loop;
end $$;


--
-- Name: FUNCTION request_reopen(p_report uuid, p_reason text, p_media jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_reopen(p_report uuid, p_reason text, p_media jsonb) IS 'The resident asks; the barangay decides. Notifies admins, writes the request to status_logs, and optionally attaches one evidence photo to report_media (0037) without changing the report''s status. SECURITY DEFINER for the same reason as cancel_report — the status_logs and report_media inserts are otherwise admin/owner-only under RLS.';


--
-- Name: retirement_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.retirement_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tanod_id uuid NOT NULL,
    status public.retirement_status DEFAULT 'pending'::public.retirement_status NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    decided_by uuid,
    denial_reason text
);


--
-- Name: TABLE retirement_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.retirement_requests IS 'A tanod''s ask to end their service. Insert only via request_retirement(); decided only via finalize_retirement(). See 0052 header.';


--
-- Name: request_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_retirement() RETURNS public.retirement_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user public.users%rowtype;
  v_req  public.retirement_requests%rowtype;
  a      record;
begin
  select * into v_user from public.users where id = auth.uid() for update;
  if not found then
    raise exception 'No such account';
  end if;

  if v_user.role <> 'tanod' then
    raise exception 'Only a tanod may request retirement';
  end if;

  if v_user.is_retired then
    raise exception 'This account has already retired';
  end if;

  if exists (
    select 1 from public.retirement_requests
     where tanod_id = v_user.id and status = 'pending'
  ) then
    raise exception 'A retirement request for this account is already waiting on the barangay';
  end if;

  insert into public.retirement_requests (tanod_id)
  values (v_user.id)
  returning * into v_req;

  for a in select id from public.users where role = 'admin' loop
    insert into public.notifications (user_id, kind, message)
    values (a.id, 'retirement',
            format('%s has requested retirement.', v_user.full_name));
  end loop;

  return v_req;
end $$;


--
-- Name: FUNCTION request_retirement(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_retirement() IS 'Tanod-only. Queues a retirement request and notifies every admin. Never changes users.is_retired itself — see finalize_retirement().';


--
-- Name: request_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_source() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  -- The caller's address as Supabase's gateway saw it. cf-connecting-ip is
  -- set by Cloudflare and cannot be supplied by the client; the others are
  -- fallbacks. Null outside an API request (SQL editor, cron, tests).
  select nullif(trim(coalesce(
           h ->> 'cf-connecting-ip',
           split_part(h ->> 'x-forwarded-for', ',', 1),
           h ->> 'x-real-ip')), '')
    from (select nullif(current_setting('request.headers', true), '')::json as h) s
$$;


--
-- Name: reroute_dispatch(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reroute_dispatch(p_dispatch uuid, p_reason text, p_to uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report   uuid;
  v_busy     text;
  v_resident uuid;
  v_tracking text;
begin
  if p_reason is null or char_length(trim(p_reason)) = 0 then
    raise exception 'A justification is required to reroute a dispatch';
  end if;

  -- Check the target before touching anything, so a refused hand-off
  -- leaves the original dispatch untouched rather than half-moved.
  if p_to is not null then
    select case when count(*) >= public.tanod_dispatch_cap() then max(r.subject) end into v_busy
      from public.dispatches d
      join public.reports r on r.id = d.report_id
     where d.tanod_id = p_to and d.state in ('assigned', 'accepted');

    if v_busy is not null then
      raise exception
        'That tanod already has the most dispatches a tanod can hold at once. Reroute to the queue instead.';
    end if;

    if not exists (select 1 from public.users
                    where id = p_to and is_dispatchable) then
      raise exception 'That tanod is not on duty and available';
    end if;
  end if;

  update public.dispatches
     set state = 'rerouted', rerouted_at = now(),
         reroute_reason = p_reason, rerouted_to = p_to
   where id = p_dispatch
     and tanod_id = auth.uid()
     and state in ('assigned', 'accepted')
  returning report_id into v_report;

  if v_report is null then
    raise exception 'Dispatch not found, not yours, or already actioned';
  end if;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (v_report, auth.uid(), 'assigned', 'assigned', 'Rerouted: ' || p_reason);

  if p_to is not null then
    insert into public.dispatches (report_id, tanod_id, assigned_by, admin_instructions)
    values (v_report, p_to, auth.uid(), 'Rerouted from a previous tanod.');

    insert into public.notifications (user_id, report_id, kind, message)
    values (p_to, v_report, 'reroute', 'A dispatch was rerouted to you.');

    -- NEW: a direct hand-off is a fresh dispatch for the resident too.
    select resident_id, tracking_id into v_resident, v_tracking
      from public.reports where id = v_report;

    insert into public.notifications (user_id, report_id, kind, message)
    values (v_resident, v_report, 'assignment',
            format('A tanod has been dispatched to your report %s.', v_tracking));
  else
    -- Back to the queue means back through proximity selection.
    -- redispatch_report -> auto_dispatch already notifies the resident
    -- once (and if) a new tanod is actually found, so nothing is added
    -- here â€” an intermediate "being rerouted" ping to the resident
    -- would be noise, not signal.
    perform public.redispatch_report(v_report, 'rerouted to queue: ' || p_reason);
  end if;

  insert into public.notifications (user_id, report_id, kind, message)
  select id, v_report, 'reroute', 'A dispatch was rerouted.'
    from public.users where role = 'admin';
end $$;


--
-- Name: reset_admin_password(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_admin_password(p_user uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'auth'
    AS $$
declare
  v_temp    text := public._temp_password();
  v_changed integer;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may reset an administrator''s password';
  end if;
  if p_user = auth.uid() then
    raise exception 'Change your own password from Set a new password instead';
  end if;
  if not exists (select 1 from public.users where id = p_user and role = 'admin') then
    raise exception 'That account is not an administrator';
  end if;

  update auth.users
     set encrypted_password = extensions.crypt(v_temp, extensions.gen_salt('bf')), updated_at = now()
   where id = p_user;
  get diagnostics v_changed = row_count;
  if v_changed <> 1 then
    raise exception 'The password was not changed';
  end if;

  update public.users set must_change_password = true where id = p_user;

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (p_user, auth.uid(), 'password_reset', 'Temporary administrator password issued');

  return v_temp;
end $$;


--
-- Name: reset_verification_overdue_mark(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_verification_overdue_mark() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if new.verification_status = 'pending'
     and old.verification_status is distinct from 'pending' then
    new.verification_overdue_notified_at := null;
  end if;
  return new;
end $$;


--
-- Name: resident_abuse_reports(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resident_abuse_reports(p_user uuid) RETURNS TABLE(report_id uuid, tracking_id text, subject text, remark text, flagged_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  select r.id, r.tracking_id, r.subject, sl.remark, sl.created_at
    from public.status_logs sl
    join public.reports r on r.id = sl.report_id
   where public.is_admin()
     and r.resident_id = p_user
     and sl.is_abusive = true
     and sl.new_status = 'rejected'
   order by sl.created_at desc
$$;


--
-- Name: FUNCTION resident_abuse_reports(p_user uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resident_abuse_reports(p_user uuid) IS 'Every report rejected AND flagged abusive for one resident, newest first. Admin only -- the where clause returns zero rows rather than raising for anyone else, same style as tanod_roster()''s own guard.';


--
-- Name: resident_remark(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resident_remark(p_remark text, p_is_system boolean) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select regexp_replace(regexp_replace(
    case
      when p_remark is null or btrim(p_remark) = '' then null
      when p_remark ~* '^(auto-dispatched|manually assigned)' then 'A tanod was assigned to your report.'
      when p_remark ~* '^(re-dispatching|rerouted)' then 'The barangay is sending another available tanod.'
      when p_remark ~* '^no tanod' then 'Waiting for an available tanod.'
      when p_remark ~* '^sla breach' then 'Past the expected date. The barangay has been alerted.'
      when p_remark ~* '^resolution target moved from' then 'The barangay changed the expected resolution date.'
      else p_remark
    end,
    '\m1 time\(s\)', '1 time', 'g'),
    'time\(s\)', 'times', 'g')
$$;


--
-- Name: FUNCTION resident_remark(p_remark text, p_is_system boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resident_remark(p_remark text, p_is_system boolean) IS 'A status-log note as a resident should read it: assignment, re-dispatch and SLA notes (tanod names, distances, system jargon) become plain wording, and "time(s)" reads properly. 0099, 0105.';


--
-- Name: retirement_requests_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retirement_requests_queue() RETURNS TABLE(id uuid, tanod_id uuid, full_name text, email text, mobile_number text, status public.retirement_status, requested_at timestamp with time zone, decided_at timestamp with time zone, decided_by uuid, decided_by_name text, denial_reason text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select r.id, r.tanod_id, u.full_name, u.email, u.mobile_number,
         r.status, r.requested_at, r.decided_at, r.decided_by, d.full_name,
         r.denial_reason
    from public.retirement_requests r
    join public.users u on u.id = r.tanod_id
    left join public.users d on d.id = r.decided_by
   order by (r.status = 'pending') desc, r.requested_at desc
$$;


--
-- Name: FUNCTION retirement_requests_queue(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.retirement_requests_queue() IS 'Retirement Requests queue. Pending first, newest first within that.';


--
-- Name: review_report(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_report(p_report uuid, p_decision text, p_remark text DEFAULT NULL::text, p_abusive boolean DEFAULT false) RETURNS public.report_status
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report   public.reports%rowtype;
  v_new      report_status;
  v_remark   text := nullif(trim(coalesce(p_remark, '')), '');
  v_abusive  boolean;
  v_strikes  integer;
  v_resident public.users%rowtype;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may review a complaint';
  end if;

  if p_decision not in ('validate', 'reject') then
    raise exception 'Unknown decision: %', p_decision;
  end if;

  select * into v_report
    from public.reports
   where id = p_report and deleted_at is null
     for update;

  if not found then
    raise exception 'No such report';
  end if;

  if v_report.status <> 'pending_review' then
    raise exception 'This complaint has already been reviewed (current status: %)',
      replace(v_report.status::text, '_', ' ');
  end if;

  if p_decision = 'reject' and v_remark is null then
    raise exception 'A reason is required when denying a complaint';
  end if;

  -- Only a reject can be abusive. A stray true on a validate call (there
  -- is no UI path that sends one, but nothing stops a direct RPC call)
  -- is silently dropped rather than raising -- this flag is additive
  -- bookkeeping, not something worth failing the whole review over.
  v_abusive := p_decision = 'reject' and coalesce(p_abusive, false);

  v_new := case p_decision when 'validate' then 'validated' else 'rejected' end::report_status;

  update public.reports
     set status = v_new
   where id = p_report;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark, is_abusive)
  values
    (p_report, auth.uid(), v_report.status, v_new,
     coalesce(v_remark,
              'Complaint accepted for action by the barangay admin.'),
     v_abusive);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          case p_decision
            when 'validate' then
              format('%s has been accepted and is now with the barangay.', v_report.tracking_id)
            else
              format('%s was not accepted. Reason: %s', v_report.tracking_id, v_remark)
          end);

  -- Auto-restriction. Counted fresh each time rather than kept as a
  -- running column on users -- this table is small per resident and a
  -- computed count can never drift out of sync with the log it is
  -- supposedly summarising, unlike a counter that has to be remembered
  -- to update everywhere the flag could change.
  if v_abusive then
    select count(*) into v_strikes
      from public.status_logs sl
      join public.reports r2 on r2.id = sl.report_id
     where r2.resident_id = v_report.resident_id
       and sl.is_abusive = true
       and sl.new_status = 'rejected';

    select * into v_resident from public.users where id = v_report.resident_id;

    if v_strikes >= 3 and v_resident.id is not null and not v_resident.is_suspended then
      perform public.set_account_suspension(
        v_report.resident_id,
        true,
        format('Automatically restricted: %s reports flagged as abusive.', v_strikes));
    end if;
  end if;

  return v_new;
end $$;


--
-- Name: FUNCTION review_report(p_report uuid, p_decision text, p_remark text, p_abusive boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.review_report(p_report uuid, p_decision text, p_remark text, p_abusive boolean) IS 'Validate Report / deny path, now with an optional abuse flag on a reject. At 3 abuse-flagged rejects for the same resident, calls set_account_suspension() itself -- same suspension, same RLS block on reports_resident_insert, same Reinstate button an admin already knows, just system-triggered instead of manual.';


--
-- Name: revoke_user_sessions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_user_sessions(p_user uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  -- Refresh tokens go with their session; an access token already issued
  -- runs out within the hour.
  delete from auth.sessions where user_id = p_user;
$$;


--
-- Name: FUNCTION revoke_user_sessions(p_user uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.revoke_user_sessions(p_user uuid) IS '0114: signs a user out on every device. Called by password-otp after an SMS password reset.';


--
-- Name: run_admin_handover_expirations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_admin_handover_expirations() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare r record;
begin
  for r in
    select id, full_name, admin_handover_role
      from public.users
     where role = 'admin'
       and admin_handover_until is not null
       and admin_handover_until <= now()
  loop
    begin
      update public.users
         set role                         = r.admin_handover_role,
             admin_handover_until         = null,
             admin_handover_role          = null,
             admin_handover_successor_id  = null
       where id = r.id;

      insert into public.account_audit (subject_id, actor_id, action, detail)
      values (r.id, null, 'stepped_down',
              format('Handover window ended automatically. Returned to %s.', r.admin_handover_role));

      insert into public.notifications (user_id, kind, message)
      values (r.id, 'verification',
              'Your administrator handover period has ended. You have been returned to your prior role.');
    exception when others then
      -- Leave this one's handover in place; the next hourly run tries
      -- again rather than losing the barangay's only administrator.
      continue;
    end;
  end loop;
end $$;


--
-- Name: run_media_cleanup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_media_cleanup() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_url    text;
  v_secret text;
begin
  if to_regclass('vault.decrypted_secrets') is null then return; end if;
  execute $q$ select max(decrypted_secret) filter (where name = 'media_cleanup_url'),
                     max(decrypted_secret) filter (where name = 'media_cleanup_secret')
                from vault.decrypted_secrets $q$
     into v_url, v_secret;
  if v_url is null or v_secret is null then return; end if;
  if not exists (select 1 from public.media_trash where queued_at < now() - interval '7 days') then return; end if;
  perform net.http_post(url := v_url,
                        headers := jsonb_build_object('Content-Type', 'application/json', 'x-cleanup-secret', v_secret),
                        body := '{}'::jsonb,
                        timeout_milliseconds := 60000);
end $_$;


--
-- Name: set_accept_deadline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_accept_deadline() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare mins integer;
begin
  if new.accept_due_at is null then
    select p.accept_minutes into mins
      from public.sla_policies p
      join public.reports r on r.category = p.category
     where r.id = new.report_id;
    if mins is not null then
      new.accept_due_at := new.assigned_at + make_interval(mins => mins);
    end if;
  end if;
  return new;
end $$;


--
-- Name: set_account_suspension(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_account_suspension(p_user uuid, p_suspend boolean, p_reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user   public.users%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  d        record;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may suspend an account';
  end if;

  select * into v_user from public.users where id = p_user for update;
  if not found then
    raise exception 'No such account';
  end if;

  if p_user = auth.uid() then
    raise exception 'You cannot suspend your own account';
  end if;

  if v_user.role = 'admin' then
    raise exception 'Administrator accounts cannot be suspended from this screen';
  end if;

  if v_user.is_suspended = p_suspend then
    raise exception 'That account is already %',
      case when p_suspend then 'suspended' else 'active' end;
  end if;

  if p_suspend and v_reason is null then
    raise exception 'A reason is required when suspending an account';
  end if;

  update public.users
     set is_suspended     = p_suspend,
         suspended_reason = case when p_suspend then v_reason end
   where id = p_user;

  -- Suspending a tanod mid-incident cannot leave the complaint parked on
  -- a phone that will never open again. Same treatment as an acceptance
  -- window that elapsed: close the dispatch, put the report back in the
  -- queue, let proximity find someone else.
  if p_suspend and v_user.role = 'tanod' then
    for d in
      update public.dispatches
         set state = 'expired'
       where tanod_id = p_user and state in ('assigned', 'accepted')
      returning report_id
    loop
      perform public.redispatch_report(d.report_id, 'assigned tanod was suspended');
    end loop;
  end if;

  insert into public.notifications (user_id, kind, message)
  values (p_user,
          'verification',
          case when p_suspend
            then format('Your account has been suspended. Reason: %s', v_reason)
            else 'Your account has been reinstated.'
          end);

  return p_suspend;
end $$;


--
-- Name: FUNCTION set_account_suspension(p_user uuid, p_suspend boolean, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_account_suspension(p_user uuid, p_suspend boolean, p_reason text) IS 'Manage User Account suspend/reinstate. Releases any live dispatch the tanod was holding back to the queue.';


--
-- Name: set_dispatch_step(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_dispatch_step(p_dispatch uuid, p_step text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_d      public.dispatches%rowtype;
  v_status report_status;
  v_owner  uuid;
  v_tick   text;
  v_line   text;
begin
  if p_step not in ('on_the_way', 'arrived') then
    raise exception 'Unknown step';
  end if;

  select * into v_d from public.dispatches
   where id = p_dispatch and tanod_id = auth.uid() and state = 'accepted'
   for update;
  if not found then
    raise exception 'Dispatch not found, not yours, or not accepted';
  end if;

  if v_d.step = p_step or (v_d.step = 'arrived' and p_step = 'on_the_way') then
    return; -- already there; a double tap is not an error
  end if;

  update public.dispatches set step = p_step where id = p_dispatch;

  insert into public.dispatch_updates (dispatch_id, author_id, kind, step)
  values (p_dispatch, auth.uid(), 'step', p_step);

  select status, resident_id, tracking_id into v_status, v_owner, v_tick
    from public.reports where id = v_d.report_id;

  v_line := case p_step
              when 'on_the_way' then 'Tanod is on the way.'
              else 'Tanod has arrived.'
            end;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (v_d.report_id, auth.uid(), v_status, v_status, v_line);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_owner, v_d.report_id, 'status_change'::notification_kind,
          case p_step
            when 'on_the_way' then 'A tanod is on the way to ' || v_tick || '.'
            else 'The tanod has arrived for ' || v_tick || '.'
          end);
end $$;


--
-- Name: set_notification_mute(public.notification_kind, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_notification_mute(p_kind public.notification_kind, p_muted boolean) RETURNS public.notification_kind[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_out notification_kind[];
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;

  if p_kind = 'verification' then
    raise exception 'Account-status notifications cannot be muted';
  end if;

  update public.users
     set muted_notification_kinds = case
           when p_muted then (
             select array_agg(distinct k) from (
               select unnest(coalesce(muted_notification_kinds, '{}')) as k
               union
               select p_kind
             ) t
           )
           else (
             select coalesce(array_agg(k), '{}') from (
               select unnest(coalesce(muted_notification_kinds, '{}')) as k
             ) t
             where k <> p_kind
           )
         end
   where id = v_uid
  returning muted_notification_kinds into v_out;

  if v_out is null then
    raise exception 'No such account';
  end if;

  return v_out;
end $$;


--
-- Name: FUNCTION set_notification_mute(p_kind public.notification_kind, p_muted boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_notification_mute(p_kind public.notification_kind, p_muted boolean) IS 'Self-service push-mute toggle, one kind at a time. verification is refused -- account-status changes are not muteable. Reading the current set needs no separate RPC: it is already on users, readable via the same self-select policy edit_profile_screen.dart already relies on.';


--
-- Name: set_report_deadline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_report_deadline() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare hrs integer;
begin
  if new.due_at is null then
    select resolution_hours into hrs
      from public.sla_policies where category = new.category;
    if hrs is not null then
      new.due_at := new.created_at + make_interval(hours => hrs);
    end if;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION set_report_deadline(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_report_deadline() IS 'Unused since 0071: the admin sets each complaint''s target date (set_resolution_target) before dispatching.';


--
-- Name: set_report_location_label(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_report_location_label(p_report uuid, p_label text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_owner uuid;
  v_label text := nullif(btrim(left(coalesce(p_label, ''), 160)), '');
begin
  if v_label is null then
    return false;
  end if;

  select resident_id into v_owner from public.reports where id = p_report;
  if not found then
    return false;
  end if;
  if v_owner is distinct from auth.uid() and coalesce(public.my_role()::text, '') <> 'admin' then
    raise exception 'not_allowed';
  end if;

  update public.reports
     set location_label = v_label
   where id = p_report
     and location_label is null;
  return found;
end $$;


--
-- Name: set_report_public(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_report_public(p_report uuid, p_public boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may publish an incident';
  end if;
  update public.reports set is_public = coalesce(p_public, false)
   where id = p_report and deleted_at is null;
  if not found then
    raise exception 'No such report';
  end if;
end $$;


--
-- Name: set_resolution_target(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_resolution_target(p_report uuid, p_due timestamp with time zone, p_reason text DEFAULT NULL::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_when   text;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_cap    integer;
  v_used   integer;
  v_extend boolean;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may change a resolution target';
  end if;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if p_due is null then
    raise exception 'A target date is required';
  end if;
  if p_due <= now() then
    raise exception 'The target date must be in the future';
  end if;
  if v_report.status in ('resolved', 'closed', 'archived', 'rejected', 'cancelled') then
    raise exception 'This complaint is already finished; its target cannot be moved';
  end if;
  if v_report.due_at is not distinct from p_due then
    return p_due;
  end if;

  -- Later than the current date: an extension, recorded and capped.
  v_extend := v_report.due_at is not null and p_due > v_report.due_at;
  if v_extend then
    select max_deadline_extensions into v_cap from public.operational_settings where id = 1;
    v_cap  := coalesce(v_cap, 2);
    v_used := public.extensions_used(p_report);
    if v_used >= v_cap then
      raise exception 'This complaint''s target date has already been extended % time(s), the limit. Hand it to a higher official instead.', v_used;
    end if;
    if v_reason is null or char_length(v_reason) < 5 or char_length(v_reason) > 300 then
      raise exception 'Give a reason (5 to 300 characters) for extending the target date';
    end if;
    insert into public.sla_extensions (report_id, requested_by, approved_by, previous_due, new_due, reason, approved_at)
    values (p_report, auth.uid(), auth.uid(), v_report.due_at, p_due, v_reason, now());
  end if;

  update public.reports set due_at = p_due where id = p_report;

  v_when := to_char(p_due at time zone 'Asia/Manila', 'FMMonth FMDD, YYYY, FMHH12:MI AM');

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, v_report.status,
          case when v_report.due_at is null
            then format('Expected to be resolved by %s.', v_when)
            else format('Expected resolution moved to %s.', v_when)
          end || case when v_extend then ' Reason: ' || v_reason else '' end);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          case when v_report.due_at is null
            then format('The barangay expects to resolve %s by %s.', v_report.tracking_id, v_when)
            else format('The expected resolution of %s is now %s.', v_report.tracking_id, v_when)
          end);

  return p_due;
end $$;


--
-- Name: FUNCTION set_resolution_target(p_report uuid, p_due timestamp with time zone, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_resolution_target(p_report uuid, p_due timestamp with time zone, p_reason text) IS 'The admin sets or moves a complaint''s target date (0071). Moving it later is an extension (0079): it needs a reason, is recorded in sla_extensions, and is capped by max_deadline_extensions.';


--
-- Name: set_verification_deadline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_verification_deadline() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if new.verification_submitted_at is not null
     and (old.verification_submitted_at is null
          or old.verification_submitted_at is distinct from new.verification_submitted_at) then
    new.verification_due_at := new.verification_submitted_at + interval '2 hours';
  end if;
  return new;
end $$;


--
-- Name: smart_duplicates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.smart_duplicates(p_report uuid) RETURNS TABLE(report_id uuid, tracking_id text, metres integer, hours_apart numeric, similarity real, status public.report_status)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'Only an administrator can see possible duplicates.' using errcode = 'insufficient_privilege';
  end if;
  return query select * from public.smart_duplicates_of(p_report);
end $$;


--
-- Name: smart_duplicates_of(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.smart_duplicates_of(p_report uuid) RETURNS TABLE(report_id uuid, tracking_id text, metres integer, hours_apart numeric, similarity real, status public.report_status)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  with k as (select * from public.smart_rules where id = 1),
       r as (select * from public.reports where id = p_report)
  select o.id, o.tracking_id,
         round(st_distance(o.geom, r.geom))::integer,
         round(extract(epoch from (r.created_at - o.created_at)) / 3600.0, 1),
         extensions.similarity(lower(o.subject || ' ' || o.description), lower(r.subject || ' ' || r.description)),
         o.status
    from r, k, public.reports o
   where o.id <> r.id
     and o.category = r.category
     and o.deleted_at is null
     and o.status not in ('rejected', 'cancelled', 'closed', 'archived')
     and o.created_at <= r.created_at
     and o.created_at > r.created_at - make_interval(hours => k.duplicate_hours)
     and st_dwithin(o.geom, r.geom, k.duplicate_metres)
     and (extensions.similarity(lower(o.subject || ' ' || o.description), lower(r.subject || ' ' || r.description)) >= k.duplicate_similarity
          or st_dwithin(o.geom, r.geom, 25))
   order by 5 desc, 3
   limit 5
$$;


--
-- Name: smart_eta(public.complaint_category); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.smart_eta(p_category public.complaint_category) RETURNS TABLE(median_hours numeric, p80_hours numeric, cases integer, sla_hours integer, basis text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  with done as (
    select extract(epoch from (r.resolved_at - r.created_at)) / 3600.0 as h
      from public.reports r
     where r.category = p_category and r.resolved_at is not null and r.deleted_at is null
       and r.resolved_at > now() - interval '180 days'
  ), st as (
    select count(*)::integer as n,
           percentile_cont(0.5) within group (order by h) as med,
           percentile_cont(0.8) within group (order by h) as p80
      from done
  )
  select case when st.n >= 5 then round(st.med::numeric, 1) else p.resolution_hours::numeric end,
         case when st.n >= 5 then round(st.p80::numeric, 1) else p.resolution_hours::numeric end,
         st.n, p.resolution_hours,
         case when st.n >= 5 then 'past cases' else 'target' end
    from st left join public.sla_policies p on p.category = p_category
$$;


--
-- Name: smart_retriage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.smart_retriage(p_report uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_n integer := 0;
  v_id uuid;
begin
  if not public.is_admin() and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Only an administrator can re-score reports.' using errcode = 'insufficient_privilege';
  end if;
  for v_id in
    select id from public.reports
     where (p_report is null and deleted_at is null
            and status not in ('resolved', 'closed', 'archived', 'rejected', 'cancelled'))
        or id = p_report
  loop
    perform public.smart_triage(v_id);
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;


--
-- Name: smart_tanod_ranking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.smart_tanod_ranking(p_report uuid) RETURNS TABLE(tanod_id uuid, full_name text, score integer, metres integer, active_jobs integer, closed_nearby integer, location_fresh boolean, reasons jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'Only an administrator can rank tanods.' using errcode = 'insufficient_privilege';
  end if;
  return query
  with c as (
    select n.tanod_id, n.full_name, n.metres,
           (select count(*)::integer from public.dispatches d
             where d.tanod_id = n.tanod_id and d.state in ('assigned', 'accepted')) as active,
           (select count(*)::integer from public.dispatches d
              join public.reports o on o.id = d.report_id
             where d.tanod_id = n.tanod_id and d.state = 'resolved'
               and d.resolved_at > now() - interval '90 days'
               and st_dwithin(o.geom, (select geom from public.reports where id = p_report), 300)) as nearby,
           public.location_is_fresh(u.last_location_at) as fresh
      from public.nearest_available_tanod(p_report) n
      join public.users u on u.id = n.tanod_id
  ), s as (
    select c.*,
           case when c.metres is null then 50 else least(round(c.metres / 20)::integer, 50) end as dist_pen,
           c.active * 15 as load_pen,
           least(c.nearby * 5, 20) as area_bonus,
           case when c.fresh then 0 else 10 end as stale_pen
      from c
  )
  select s.tanod_id, s.full_name,
         greatest(0, 100 - s.dist_pen - s.load_pen + s.area_bonus - s.stale_pen),
         round(s.metres)::integer, s.active, s.nearby, s.fresh,
         jsonb_build_array(
           jsonb_build_object('factor', 'distance',
             'detail', case when s.metres is null then 'no location yet' else round(s.metres) || ' m away' end,
             'points', -s.dist_pen),
           jsonb_build_object('factor', 'workload', 'detail', s.active || ' job(s) in hand', 'points', -s.load_pen),
           jsonb_build_object('factor', 'knows the area', 'detail', s.nearby || ' case(s) closed within 300 m, last 90 days',
             'points', s.area_bonus),
           jsonb_build_object('factor', 'location', 'detail', case when s.fresh then 'live' else 'not recent' end,
             'points', -s.stale_pen))
    from s
   order by 3 desc, s.metres nulls last;
end $$;


--
-- Name: report_triage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.report_triage (
    report_id uuid NOT NULL,
    score smallint NOT NULL,
    level text NOT NULL,
    reasons jsonb NOT NULL,
    possible_duplicates smallint DEFAULT 0 NOT NULL,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT report_triage_level_check CHECK ((level = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT report_triage_score_check CHECK (((score >= 0) AND (score <= 100)))
);


--
-- Name: TABLE report_triage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.report_triage IS '0122: SMART triage of each report: score 0-100, level, and the reasons [{factor, detail, points}]. Written only by smart_triage().';


--
-- Name: smart_triage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.smart_triage(p_report uuid) RETURNS public.report_triage
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  r       public.reports%rowtype;
  k       public.smart_rules%rowtype;
  v_text  text;
  v_pts   integer;
  v_kw    integer := 0;
  v_score integer := 0;
  v_why   jsonb := '[]';
  v_lvl   smallint;
  v_haz   text;
  v_n     integer;
  v_dups  integer;
  v_hour  integer;
  g       jsonb;
  v_out   public.report_triage;
begin
  select * into r from public.reports where id = p_report;
  if not found then return null; end if;
  select * into k from public.smart_rules where id = 1;

  -- the kind of complaint
  v_pts := coalesce((k.category_points ->> r.category::text)::integer, 0);
  v_score := v_pts;
  v_why := v_why || jsonb_build_object('factor', 'category', 'detail', r.category::text, 'points', v_pts);

  -- words
  v_text := lower(r.subject || ' ' || r.description);
  for g in select * from jsonb_array_elements(k.keyword_groups) loop
    if v_text ~ (g ->> 'pattern') then
      v_pts := least((g ->> 'points')::integer, k.keyword_cap - v_kw);
      if v_pts > 0 then
        v_kw := v_kw + v_pts;
        v_why := v_why || jsonb_build_object('factor', 'words', 'detail', g ->> 'label',
                                             'points', v_pts,
                                             'matched', substring(v_text from (g ->> 'pattern')));
      end if;
    end if;
  end loop;
  v_score := v_score + v_kw;

  -- hazard zone
  select z.level, z.hazard into v_lvl, v_haz
    from public.hazard_zones z
   where st_intersects(z.geom, r.geom::geometry)
   order by z.level desc, z.hazard
   limit 1;
  if v_lvl is not null then
    v_pts := coalesce((k.hazard_points ->> v_lvl::text)::integer, 0);
    v_score := v_score + v_pts;
    v_why := v_why || jsonb_build_object('factor', 'hazard zone',
      'detail', format('NOAH %s zone, %s', v_haz, (array['low', 'medium', 'high'])[v_lvl]), 'points', v_pts);
  end if;

  -- other residents, same kind, close in place and time
  select count(distinct o.resident_id) into v_n
    from public.reports o
   where o.id <> r.id
     and o.category = r.category
     and o.resident_id <> r.resident_id
     and o.deleted_at is null
     and o.status not in ('rejected', 'cancelled')
     and o.created_at between r.created_at - make_interval(hours => k.corroboration_hours)
                          and r.created_at + make_interval(hours => k.corroboration_hours)
     and st_dwithin(o.geom, r.geom, k.corroboration_metres);
  if v_n > 0 then
    v_pts := least(v_n * k.corroboration_points, k.corroboration_cap);
    v_score := v_score + v_pts;
    v_why := v_why || jsonb_build_object('factor', 'nearby reports',
      'detail', format('%s other resident%s reported this within %s m', v_n, case when v_n = 1 then '' else 's' end,
                       k.corroboration_metres),
      'points', v_pts);
  end if;

  -- night, for safety kinds
  v_hour := extract(hour from r.created_at at time zone 'Asia/Manila');
  if (v_hour >= 22 or v_hour < 5)
     and r.category in ('peace_order_nuisance', 'public_safety_infrastructure', 'traffic_violation') then
    v_score := v_score + k.night_points;
    v_why := v_why || jsonb_build_object('factor', 'night', 'detail', format('filed at %s:00', v_hour),
                                         'points', k.night_points);
  end if;

  select count(*) into v_dups from public.smart_duplicates_of(r.id);

  v_score := greatest(0, least(100, v_score));
  insert into public.report_triage as t (report_id, score, level, reasons, possible_duplicates, computed_at)
  values (r.id, v_score,
          case when v_score >= k.urgent_from then 'urgent'
               when v_score >= k.high_from   then 'high'
               when v_score >= k.normal_from then 'normal'
               else 'low' end,
          v_why, v_dups, now())
  on conflict (report_id) do update
     set score = excluded.score, level = excluded.level, reasons = excluded.reasons,
         possible_duplicates = excluded.possible_duplicates, computed_at = excluded.computed_at
  returning * into v_out;
  return v_out;
exception when others then
  raise warning 'smart_triage(%) failed: %', p_report, sqlerrm;
  return null;
end $$;


--
-- Name: FUNCTION smart_triage(p_report uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.smart_triage(p_report uuid) IS '0122: scores one report from smart_rules and stores it in report_triage. Internal; called by triggers and smart_retriage().';


--
-- Name: status_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.status_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_id uuid NOT NULL,
    changed_by uuid,
    old_status public.report_status,
    new_status public.report_status NOT NULL,
    remark text,
    is_system boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    prev_hash text,
    entry_hash text,
    is_abusive boolean DEFAULT false NOT NULL
);


--
-- Name: COLUMN status_logs.entry_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.status_logs.entry_hash IS 'SHA-256 over this entry and the previous entry_hash for the same report. See 0015.';


--
-- Name: COLUMN status_logs.is_abusive; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.status_logs.is_abusive IS 'Set only alongside a reject decision in review_report() -- an admin marking this specific denial as bad-faith (fabricated, malicious, spam) rather than an honest mistake (wrong barangay, duplicate, not enough detail). Meaningless on any other new_status; review_report() never sets it true for anything but a reject. Counted per resident to drive the 3-strike auto-restriction below.';


--
-- Name: status_log_fingerprint(public.status_logs); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.status_log_fingerprint(l public.status_logs) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select concat_ws('|',
    l.id::text, l.report_id::text, coalesce(l.changed_by::text, ''),
    coalesce(l.old_status::text, ''), l.new_status::text,
    coalesce(l.remark, ''), l.is_system::text,
    to_char(l.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'))
$$;


--
-- Name: step_down_as_admin(public.user_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.step_down_as_admin(p_new_role public.user_role DEFAULT 'resident'::public.user_role) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_left integer;
  v_me   public.users%rowtype;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may step down';
  end if;

  if p_new_role = 'admin' then
    raise exception 'Choose the role you are returning to, not administrator';
  end if;

  select * into v_me from public.users where id = auth.uid() for update;

  select count(*) into v_left from public.users
   where role = 'admin' and id <> auth.uid() and not is_suspended;

  -- The guard. Appoint your successor first; then this will let you go.
  if v_left = 0 then
    raise exception
      'You are the only administrator. Appoint your successor before stepping down, or the barangay will be locked out of its own system.';
  end if;

  update public.users set role = p_new_role where id = auth.uid();

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (v_me.id, v_me.id, 'stepped_down',
          format('Returned to %s. %s administrator(s) remain.', p_new_role, v_left));

  insert into public.notifications (user_id, kind, message)
  select id, 'verification',
         format('%s has stepped down as barangay administrator.', v_me.full_name)
    from public.users where role = 'admin' and id <> v_me.id;

  return v_left;
end $$;


--
-- Name: submit_additional_details(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_additional_details(p_request uuid, p_details text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report    uuid;
  v_asker     uuid;
  v_answered  timestamptz;
  v_status    report_status;
  v_owner     uuid;
  v_ticket    text;
  v_details   text := nullif(trim(p_details), '');
  v_media     jsonb := coalesce(p_media, '[]'::jsonb);
  v_item      jsonb;
begin
  if jsonb_typeof(v_media) <> 'array' then
    raise exception 'p_media must be a JSON array of {media_url, mime_type, bytes}'
      using errcode = 'invalid_parameter_value';
  end if;
  if v_details is null and jsonb_array_length(v_media) = 0 then
    raise exception 'Please add the details or a photo';
  end if;
  if char_length(coalesce(v_details, '')) > 500 then
    raise exception 'Keep the details under 500 characters';
  end if;

  select q.report_id, q.requested_by, q.responded_at
    into v_report, v_asker, v_answered
    from public.detail_requests q
   where q.id = p_request;

  if v_report is null then
    raise exception 'Request not found';
  end if;

  select status, resident_id, tracking_id
    into v_status, v_owner, v_ticket
    from public.reports
   where id = v_report and deleted_at is null;

  if v_owner is distinct from auth.uid() then
    raise exception 'Only the resident who filed this report can answer';
  end if;
  if v_answered is not null then
    raise exception 'This request has already been answered';
  end if;
  if v_status not in ('assigned', 'in_progress', 'offline_investigation') then
    raise exception 'This report is no longer being worked on';
  end if;

  update public.detail_requests
     set response = v_details,
         responded_at = now()
   where id = p_request;

  -- Same insert idiom as request_reopen (0037): report_media_cap and
  -- the URL pins still apply.
  for v_item in select value from jsonb_array_elements(v_media)
  loop
    insert into public.report_media (report_id, media_url, mime_type, bytes)
    values (v_report,
            v_item ->> 'media_url',
            v_item ->> 'mime_type',
            (v_item ->> 'bytes')::integer);
  end loop;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark)
  values
    (v_report, auth.uid(), v_status, v_status,
     'Resident sent more details: ' ||
       coalesce(v_details, 'photo/video attached'));

  -- Whoever asked, and the tanod now holding the case if that's someone
  -- else (a reroute in between).
  insert into public.notifications (user_id, report_id, kind, message)
  -- (the union already drops a duplicate recipient)
  select u, v_report, 'status_change'::notification_kind,
         'The resident sent more details for ' || v_ticket || '.'
    from (
      select v_asker as u
      union
      select d.tanod_id from public.dispatches d
       where d.report_id = v_report and d.state = 'accepted'
    ) t
   where u is not null;
end $$;


--
-- Name: FUNCTION submit_additional_details(p_request uuid, p_details text, p_media jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.submit_additional_details(p_request uuid, p_details text, p_media jsonb) IS 'The resident answers an open detail request with text and/or media (into report_media under the usual caps and URL pins). Logs to status_logs and notifies the asker and the current tanod. 0065.';


--
-- Name: submit_field_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_field_report(p_dispatch uuid, p_text text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_report uuid; v_status report_status; v_tick text;
begin
  update public.dispatches
     set state = 'resolved', field_report_text = p_text, resolved_at = now()
   where id = p_dispatch and tanod_id = auth.uid() and state = 'accepted'
  returning report_id into v_report;

  if v_report is null then
    raise exception 'Dispatch not found, not yours, or not in an accepted state';
  end if;

  update public.reports
     set resolution_submitted_at = now(), resolution_returned_reason = null
   where id = v_report
  returning status, tracking_id into v_status, v_tick;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (v_report, auth.uid(), v_status, v_status,
          'Resolution report submitted by the tanod, waiting for the barangay''s approval.');

  insert into public.notifications (user_id, report_id, kind, message)
  select u.id, v_report, 'status_change',
         'A tanod submitted the resolution of ' || v_tick || '. Review and approve it.'
    from public.users u where u.role = 'admin';
end $$;


--
-- Name: sweep_awaiting_units(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_awaiting_units() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  r      record;
  v_hours smallint;
begin
  select awaiting_alert_hours into v_hours from public.operational_settings where id = 1;

  for r in
    select id, awaiting_unit_since
      from public.reports
     where awaiting_unit_since is not null
       and deleted_at is null
       and status in ('pending_review', 'validated')
     order by awaiting_unit_since
  loop
    if r.awaiting_unit_since < now() - make_interval(hours => v_hours)
       and not exists (
         select 1 from public.notifications n
          where n.report_id = r.id and n.kind = 'escalation') then
      insert into public.notifications (user_id, report_id, kind, message)
      select u.id, r.id, 'escalation',
             format('A report has been waiting over %s hours with no tanod on duty in range.', v_hours)
        from public.users u where u.role = 'admin';
    end if;

    perform public.auto_dispatch(r.id);
  end loop;
end $$;


--
-- Name: sweep_overdue_reports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_overdue_reports() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  with late as (
    update public.reports
       set overdue_notified_at = now()
     where due_at is not null
       and due_at < now()
       and (overdue_notified_at is null or overdue_notified_at < due_at)
       and status not in ('resolved', 'closed', 'archived', 'rejected', 'cancelled')
       and deleted_at is null
    returning id, tracking_id
  ),
  to_admins as (
    insert into public.notifications (user_id, report_id, kind, message)
    select u.id, l.id, 'sla_warning',
           'Complaint ' || l.tracking_id || ' is overdue: its target date has passed.'
      from late l cross join public.users u
     where u.role = 'admin'
    returning 1
  )
  insert into public.notifications (user_id, report_id, kind, message)
  select d.tanod_id, l.id, 'sla_warning',
         'Your dispatch ' || l.tracking_id || ' is overdue: its target date has passed.'
    from late l
    join public.dispatches d on d.report_id = l.id and d.state in ('assigned', 'accepted');
end $$;


--
-- Name: FUNCTION sweep_overdue_reports(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sweep_overdue_reports() IS '0072: tells admins and the dispatched tanod once when an admin-set deadline passes. Escalation is the admin''s referral (refer_report).';


--
-- Name: sweep_overdue_verifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_overdue_verifications() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- Mark first and notify from what was marked, matching the shape of
  -- the other two sweeps. A row can only be returned by the UPDATE once,
  -- so it can only generate one round of notifications however often
  -- this runs.
  with newly_overdue as (
    update public.users u
       set verification_overdue_notified_at = now()
     where u.verification_status = 'pending'
       and u.verification_due_at < now()
       and u.verification_overdue_notified_at is null
    returning u.id, u.full_name
  )
  insert into public.notifications (user_id, kind, message)
  select a.id, 'sla_warning',
         'Account verification for ' || n.full_name
           || ' has passed the 2-hour limit.'
    from newly_overdue n
    cross join public.users a
   where a.role = 'admin'
     and not a.is_suspended;
end $$;


--
-- Name: FUNCTION sweep_overdue_verifications(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sweep_overdue_verifications() IS 'Notifies admins once per account when its two-hour verification window elapses. Idempotent: the UPDATE that marks the account is what drives the notification, so repeated runs cannot duplicate it.';


--
-- Name: sweep_unaccepted_dispatches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_unaccepted_dispatches() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare r record;
begin
  for r in
    update public.dispatches
       set state = 'expired'
     where state = 'assigned' and accept_due_at < now()
    returning id, report_id, tanod_id
  loop
    insert into public.notifications (user_id, report_id, kind, message)
    select u.id, r.report_id, 'sla_warning',
           'A tanod did not respond to a dispatch within the acceptance window.'
      from public.users u where u.role = 'admin';

    -- The report does not stay parked on a dispatch nobody accepted.
    perform public.redispatch_report(r.report_id, 'acceptance window elapsed');
  end loop;
end $$;


--
-- Name: sync_dispatchable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_dispatchable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  new.is_dispatchable := coalesce(
    new.role = 'tanod'
    and new.duty_status = 'on_duty'
    and new.verification_status = 'verified'
    and not new.is_suspended
    and not new.is_retired, false);
  return new;
end $$;


--
-- Name: system_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_usage() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  month_start timestamptz := date_trunc('month', now() at time zone 'Asia/Manila') at time zone 'Asia/Manila';
begin
  if not public.is_admin() then
    raise exception 'admins only';
  end if;
  return json_build_object(
    'db_bytes',      pg_database_size(current_database()),
    'storage_bytes', coalesce((select sum((metadata->>'size')::bigint) from storage.objects), 0),
    'active_users',  (select count(*) from auth.users where last_sign_in_at >= month_start),
    'month_start',   month_start
  );
end $$;


--
-- Name: take_case(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_case(p_report uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_h uuid; v_name text;
begin
  if not public.is_admin() then raise exception 'Only an administrator may take a case'; end if;
  select handler_id into v_h from public.reports where id = p_report and deleted_at is null for update;
  if not found then raise exception 'No such report'; end if;
  if v_h = auth.uid() then return; end if;
  if v_h is not null then
    select public.display_name(full_name) into v_name from public.users where id = v_h;
    raise exception '% is already handling this case. Use Take over.', coalesce(v_name, 'Another administrator');
  end if;
  perform set_config('smartsumbong.handler_change', 'on', true);
  update public.reports set handler_id = auth.uid(), handled_since = now() where id = p_report;
  perform set_config('smartsumbong.handler_change', 'off', true);
  insert into public.case_handler_log (report_id, admin_id, action) values (p_report, auth.uid(), 'take');
end $$;


--
-- Name: take_over_case(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_over_case(p_report uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_h      uuid;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_me     text;
  v_track  text;
begin
  if not public.is_admin() then raise exception 'Only an administrator may take over a case'; end if;
  if v_reason is null or char_length(v_reason) < 3 or char_length(v_reason) > 300 then
    raise exception 'Give a reason for taking over (the current handler sees it)';
  end if;
  select handler_id, tracking_id into v_h, v_track from public.reports where id = p_report and deleted_at is null for update;
  if not found then raise exception 'No such report'; end if;
  if v_h = auth.uid() then return; end if;
  perform set_config('smartsumbong.handler_change', 'on', true);
  update public.reports set handler_id = auth.uid(), handled_since = now() where id = p_report;
  perform set_config('smartsumbong.handler_change', 'off', true);
  insert into public.case_handler_log (report_id, admin_id, action, previous_id, reason)
  values (p_report, auth.uid(), case when v_h is null then 'take' else 'take_over' end, v_h, v_reason);
  if v_h is not null then
    select public.display_name(full_name) into v_me from public.users where id = auth.uid();
    insert into public.notifications (user_id, report_id, kind, message)
    values (v_h, p_report, 'status_change', coalesce(v_me, 'Another administrator') || ' took over ' || v_track || ' from you: ' || v_reason);
  end if;
end $$;


--
-- Name: take_rate_slot(text, integer, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_rate_slot(p_bucket text, p_max integer, p_window interval) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_now  timestamptz := now();
  v_hits integer;
begin
  insert into public.rate_limit_hits as r (bucket, window_start, hits)
  values (p_bucket, v_now, 1)
  on conflict (bucket) do update
     set hits = case when r.window_start < v_now - p_window then 1 else r.hits + 1 end,
         window_start = case when r.window_start < v_now - p_window then v_now else r.window_start end
  returning hits into v_hits;

  if v_hits = 1 then
    delete from public.rate_limit_hits where window_start < v_now - interval '1 day';
  end if;
  return v_hits <= p_max;
end $$;


--
-- Name: FUNCTION take_rate_slot(p_bucket text, p_max integer, p_window interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.take_rate_slot(p_bucket text, p_max integer, p_window interval) IS '0116: true while bucket has had at most p_max calls in the current p_window. Edge Functions only (service role).';


--
-- Name: tanod_dispatch_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tanod_dispatch_cap() RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce((select max_active_dispatches from public.operational_settings limit 1), 5)
$$;


--
-- Name: tanod_roster(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tanod_roster(p_report uuid) RETURNS TABLE(tanod_id uuid, full_name text, duty_status public.duty_state, assignable boolean, unavailable_why text, metres double precision, location_fresh boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select u.id,
         u.full_name,
         u.duty_status,
         u.is_dispatchable and coalesce(b.n, 0) < public.tanod_dispatch_cap(),
         case
           when coalesce(b.n, 0) >= public.tanod_dispatch_cap() then 'Has ' || b.n || ' dispatches (the most at once)'
           when u.is_suspended                then 'Suspended'
           when u.verification_status <> 'verified' then 'Not yet verified'
           when coalesce(u.duty_status, 'offline') <> 'on_duty'
             then initcap(replace(coalesce(u.duty_status, 'offline')::text, '_', ' '))
           else null
         end,
         st_distance(u.last_geom, r.geom),
         public.location_is_fresh(u.last_location_at)
    from public.users u
    cross join public.reports r
    left join lateral (
      select count(*)::int as n from public.dispatches d
       where d.tanod_id = u.id and d.state in ('assigned', 'accepted')) b on true
   where r.id = p_report
     and u.role = 'tanod'
   order by (u.is_dispatchable and coalesce(b.n, 0) < public.tanod_dispatch_cap()) desc,
            coalesce(b.n, 0),
            st_distance(u.last_geom, r.geom) nulls last,
            u.full_name
$$;


--
-- Name: FUNCTION tanod_roster(p_report uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tanod_roster(p_report uuid) IS 'Every tanod with availability and distance, for the assign screen. Available first, then nearest. assignable_tanods remains the authoritative "who may take this".';


