--
-- Name: dispatch_updates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.dispatch_updates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    dispatch_id uuid NOT NULL,
    author_id uuid NOT NULL,
    kind text NOT NULL,
    step text,
    body text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dispatch_updates_body_check CHECK (((body IS NULL) OR (char_length(body) <= 2000))),
    CONSTRAINT dispatch_updates_kind_check CHECK ((kind = ANY (ARRAY['note'::text, 'step'::text]))),
    CONSTRAINT dispatch_updates_shape CHECK ((((kind = 'step'::text) AND (step IS NOT NULL)) OR ((kind = 'note'::text) AND (step IS NULL)))),
    CONSTRAINT dispatch_updates_step_check CHECK ((step = ANY (ARRAY['on_the_way'::text, 'arrived'::text])))
);


--
-- Name: TABLE dispatch_updates; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.dispatch_updates IS 'The dispatch window thread (0069): tanod notes, admin replies and the On the way / Arrived steps. Readable by the dispatched tanod and admins; written only through post_dispatch_update() and set_dispatch_step().';


--
-- Name: dispatches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.dispatches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_id uuid NOT NULL,
    tanod_id uuid NOT NULL,
    assigned_by uuid NOT NULL,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    admin_instructions text,
    state public.dispatch_state DEFAULT 'assigned'::public.dispatch_state NOT NULL,
    accept_due_at timestamp with time zone,
    accepted_at timestamp with time zone,
    is_primary boolean DEFAULT false NOT NULL,
    rerouted_at timestamp with time zone,
    reroute_reason text,
    rerouted_to uuid,
    field_report_text text,
    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    step text,
    CONSTRAINT dispatches_admin_instructions_check CHECK ((char_length(admin_instructions) <= 500)),
    CONSTRAINT dispatches_field_report_text_check CHECK ((char_length(field_report_text) <= 300)),
    CONSTRAINT dispatches_reroute_reason_check CHECK ((char_length(reroute_reason) <= 200)),
    CONSTRAINT dispatches_step_check CHECK ((step = ANY (ARRAY['on_the_way'::text, 'arrived'::text]))),
    CONSTRAINT reroute_needs_reason CHECK (((rerouted_at IS NULL) OR (reroute_reason IS NOT NULL)))
);


--
-- Name: escalation_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.escalation_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_id uuid NOT NULL,
    dispatch_id uuid,
    requested_by uuid NOT NULL,
    reason text NOT NULL,
    suggested_office text,
    status text DEFAULT 'pending'::text NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decided_office text,
    decision_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT escalation_requests_reason_check CHECK (((char_length(TRIM(BOTH FROM reason)) >= 1) AND (char_length(TRIM(BOTH FROM reason)) <= 1000))),
    CONSTRAINT escalation_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'denied'::text])))
);


--
-- Name: feedback; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.feedback (
