    CONSTRAINT hazard_zones_level_check CHECK (((level >= 1) AND (level <= 3)))
);


--
-- Name: TABLE hazard_zones; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hazard_zones IS '0121: NOAH flood and storm-surge zones (level 1 low to 3 high), from the portal''s hazards.geojson.';


--
-- Name: hazard_zones_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.hazard_zones ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.hazard_zones_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: hotline_groups; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hotline_groups (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    parent_id uuid,
    name text NOT NULL,
    display text DEFAULT 'inline'::text NOT NULL,
    icon text,
    sort_order smallint DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hotline_groups_display_check CHECK ((display = ANY (ARRAY['inline'::text, 'link'::text]))),
    CONSTRAINT hotline_groups_name_check CHECK (((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 120)))
);


--
-- Name: TABLE hotline_groups; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hotline_groups IS 'Sections of the emergency directory. A group with a parent appears inside that parent''s screen — "Pasay City General Hospital" under "Pasay City Hotlines". Maintained by the barangay through the admin portal, because a hotline that only a developer can correct is one that will eventually be wrong.';


--
-- Name: hotline_numbers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hotline_numbers (
