    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hotline_numbers_number_check CHECK (((length(TRIM(BOTH FROM number)) >= 3) AND (length(TRIM(BOTH FROM number)) <= 32)))
);


--
-- Name: COLUMN hotline_numbers.number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hotline_numbers.number IS 'Stored as the barangay types it, spacing included, because that is how it appears on their own signage and a resident matching the two should not have to squint. Dialling strips non-digits client-side.';


--
