);


--
-- Name: TABLE login_failure_sources; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.login_failure_sources IS '0114: how many failed sign-ins each network address has reported in the current 15-minute window. Read and written only by register_login_failure.';


