    CONSTRAINT look_shares_spot_dir_check CHECK ((spot_dir = ANY (ARRAY['N'::text, 'NE'::text, 'E'::text, 'SE'::text, 'S'::text, 'SW'::text, 'W'::text, 'NW'::text]))),
    CONSTRAINT look_shares_spot_metres_check CHECK (((spot_metres IS NULL) OR ((spot_metres >= 0) AND (spot_metres <= 1000))))
);


