-- Name: TABLE media_trash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.media_trash IS '0118: identity-photo addresses no longer used, waiting a week before media-cleanup deletes the file (if still unused).';


--
