-- Name: profile_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.profile_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    new_full_name text,
    id_type public.id_document_type,
    id_image_url text,
    reason text,
    status text DEFAULT 'pending'::text NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT profile_request_has_value CHECK ((((kind = 'full_name'::text) AND (new_full_name IS NOT NULL)) OR ((kind = 'id_document'::text) AND (id_image_url IS NOT NULL) AND (id_type IS NOT NULL)))),
    CONSTRAINT profile_requests_decision_note_check CHECK ((char_length(decision_note) <= 300)),
    CONSTRAINT profile_requests_id_image_url_check CHECK (((id_image_url IS NULL) OR public.is_media_url(id_image_url))),
    CONSTRAINT profile_requests_kind_check CHECK ((kind = ANY (ARRAY['full_name'::text, 'id_document'::text]))),
    CONSTRAINT profile_requests_new_full_name_check CHECK (((char_length(new_full_name) >= 3) AND (char_length(new_full_name) <= 120))),
    CONSTRAINT profile_requests_reason_check CHECK ((char_length(reason) <= 300)),
    CONSTRAINT profile_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'declined'::text])))
);


