    CONSTRAINT report_evidence_media_url_check CHECK (public.is_barangay_media_url(media_url)),
    CONSTRAINT report_evidence_mime_type_check CHECK ((mime_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text])))
);


