--
-- Name: smart_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.smart_rules (
    id smallint DEFAULT 1 NOT NULL,
    category_points jsonb DEFAULT '{"other": 10, "animal_welfare": 15, "barangay_service": 10, "traffic_violation": 20, "street_obstruction": 20, "peace_order_nuisance": 30, "environmental_waste_hazard": 25, "public_safety_infrastructure": 35}'::jsonb NOT NULL,
    keyword_groups jsonb DEFAULT '[{"label": "fire", "points": 30, "pattern": "\\m(fire|sunog|nasunog|nasusunog|apoy|usok|smoke)\\M"}, {"label": "weapon", "points": 30, "pattern": "\\m(gun|baril|binaril|knife|kutsilyo|patalim|saksak|sinaksak|stabbed|shooting|holdap|hold-?up|robbery|nanakawan)\\M"}, {"label": "injury", "points": 30, "pattern": "\\m(injured|injury|bleeding|blood|sugat|sugatan|nasugatan|dugo|duguan|unconscious|walang malay)\\M"}, {"label": "gas leak", "points": 30, "pattern": "\\m(gas leak|tagas ng gas|amoy gas|lpg)\\M"}, {"label": "live wire", "points": 25, "pattern": "\\m(live wire|kuryente|nakuryente|sparking|spark|kawad|transformer)\\M"}, {"label": "collapse", "points": 25, "pattern": "\\m(collapsed?|gumuho|guho|bumagsak|natumba|nabuwal|fallen tree)\\M"}, {"label": "accident", "points": 25, "pattern": "\\m(accident|aksidente|bangga|nabangga|banggaan|collision|crash)\\M"}, {"label": "fight", "points": 20, "pattern": "\\m(fight|fighting|nag-?aaway|rambol|riot|suntukan|bugbog|binugbog|gulo)\\M"}, {"label": "flooding", "points": 15, "pattern": "\\m(flood|flooding|flooded|baha|binaha|bumaha|lubog|lumubog)\\M"}, {"label": "vulnerable", "points": 10, "pattern": "\\m(child|children|bata|mga bata|elderly|matanda|senior|lola|lolo|pwd|buntis|pregnant)\\M"}]'::jsonb NOT NULL,
    keyword_cap smallint DEFAULT 45 NOT NULL,
    hazard_points jsonb DEFAULT '{"1": 5, "2": 10, "3": 15}'::jsonb NOT NULL,
    corroboration_metres integer DEFAULT 150 NOT NULL,
    corroboration_hours integer DEFAULT 48 NOT NULL,
    corroboration_points smallint DEFAULT 8 NOT NULL,
    corroboration_cap smallint DEFAULT 24 NOT NULL,
    night_points smallint DEFAULT 5 NOT NULL,
    urgent_from smallint DEFAULT 70 NOT NULL,
    high_from smallint DEFAULT 45 NOT NULL,
    normal_from smallint DEFAULT 25 NOT NULL,
    duplicate_metres integer DEFAULT 100 NOT NULL,
    duplicate_hours integer DEFAULT 72 NOT NULL,
    duplicate_similarity real DEFAULT 0.3 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT smart_rules_check CHECK (((urgent_from > high_from) AND (high_from > normal_from) AND (normal_from > 0))),
    CONSTRAINT smart_rules_id_check CHECK ((id = 1))
);


--
-- Name: TABLE smart_rules; Type: COMMENT; Schema: public; Owner: -
